// Maha PWD Estimator - Main Logic


// SSR data → see ssr_data.js

var _unsub_pay=null,_unsub_user=null;
var STORE_KEY='atp_maha_pwd_v1';
/* SCADA Settings */
var CANCEL_SCADA=false; /* if true, SCADA deduction will not apply */
var CUSTOM_SCADA_VAL=-126; /* default SCADA value (concrete, per cum), can be changed */
var CUSTOM_SCADA_BT=-63;  /* BT SCADA value (per cum), can be changed in Settings */

/* Toggle Cancel SCADA - button in Settings tab */
function toggleCancelSCADA(){
  CANCEL_SCADA=!CANCEL_SCADA;
  var btn=document.getElementById('scadaCancelBtn');
  if(btn){
    if(CANCEL_SCADA){
      btn.textContent='✅ SCADA Cancelled';
      btn.style.background='#e8f5e9';
      btn.style.color='#2e7d32';
      btn.style.borderColor='#2e7d32';
    } else {
      btn.textContent='❌ SCADA Deduction Active';
      btn.style.background='#fff';
      btn.style.color='#c62828';
      btn.style.borderColor='#c62828';
    }
  }
  updateAll();
  showToast(CANCEL_SCADA?'✅ SCADA Deduction cancelled — new items will not have SCADA':'❌ SCADA Deduction is active','info');
}

/* ── ONLY GROUND FLOOR MODE (Settings button) ─────────────────────────────
   ON = floor is not shown anywhere in Measurement / Abstract / Rate Analysis (no floor column either).
   Depth / lift / height band items (flBands) are exempt — their band dropdown stays as it is. */
var GF_ONLY=false;
function gfOff(it){return !!GF_ONLY&&!flBands(it);}                      /* does Ground-Floor-Only mode apply to this item? */
function gfColsOff(){return !!GF_ONLY&&!items.some(function(x){return !!flBands(x);});}   /* should the floor column be hidden? */
/* remove the floor column cell (grid column idx); if a colspan covers it, reduce the colspan by 1 */
function gfStripCol(tbl,idx){
  if(!gfColsOff()||!tbl)return;
  var trs=tbl.querySelectorAll('tbody tr'),t,c,pos,cells,sp;
  for(t=0;t<trs.length;t++){
    cells=trs[t].children;pos=0;
    for(c=0;c<cells.length;c++){
      sp=cells[c].colSpan||1;
      if(idx>=pos&&idx<pos+sp){if(sp>1)cells[c].colSpan=sp-1;else trs[t].removeChild(cells[c]);break;}
      pos+=sp;
    }
  }
}
/* Measurement: give the floor column cell 'noprt' (visible on screen, not in print) */
function gfPrtCol(tbl,idx){
  if(!tbl)return;
  var on=gfColsOff(),trs=tbl.querySelectorAll('tbody tr'),t,c,pos,cells,sp;
  for(t=0;t<trs.length;t++){
    cells=trs[t].children;pos=0;
    for(c=0;c<cells.length;c++){
      sp=cells[c].colSpan||1;
      if(idx>=pos&&idx<pos+sp){if(sp===1)cells[c].classList.toggle('noprt',on);break;}
      pos+=sp;
    }
  }
}
function gfHead(){
  var off=gfColsOff(),a=document.querySelectorAll('#p3 thead th'),m=document.querySelectorAll('#p5 thead th');
  if(a[4])a[4].style.display=off?'none':'';   /* Abstract: remove the Floor column */
  if(m[2])m[2].classList.toggle('noprt',off);  /* Measurement: stays on screen, not printed */
}
function gfBtnRefresh(){
  var b=document.getElementById('gfOnlyBtn');if(!b)return;
  if(GF_ONLY){b.textContent='\u2705 Only Ground Floor \u2014 ON';b.style.background='#e8f5e9';b.style.color='#2e7d32';b.style.borderColor='#2e7d32';}
  else{b.textContent='\u2b1c Only Ground Floor \u2014 OFF';b.style.background='#fff';b.style.color='#455a64';b.style.borderColor='#90a4ae';}
}
function toggleGFOnly(){
  var on=!GF_ONLY,n=0;
  if(on){
    items.forEach(function(it){if(flBands(it))return;(it.rows||[]).forEach(function(r){if(parseInt(r.fl,10)>0)n++;});});
    if(n&&!confirm(n+' measurement row(s) have 1st/2nd... floor selected. If "Only Ground Floor" is turned ON, all of them will be treated as Ground Floor (turning it OFF restores the floors). Continue?'))return;
    items.forEach(function(it){if(flBands(it))return;(it.rows||[]).forEach(function(r){if(parseInt(r.fl,10)>0){r._flBak=r.fl;r.fl=0;}});});
  }else{
    items.forEach(function(it){(it.rows||[]).forEach(function(r){if(r._flBak!=null){r.fl=r._flBak;delete r._flBak;}});});
  }
  GF_ONLY=on;gfBtnRefresh();gfHead();updateAll();
  var hasBand=items.some(function(x){return !!flBands(x);});
  showToast(on?(hasBand?'\u2705 Only Ground Floor ON \u2014 depth/lift band items exist, so the Floor column is kept (other items have no floor)':'\u2705 Only Ground Floor ON \u2014 floor will not be shown anywhere'):'Only Ground Floor OFF \u2014 floors are back','info');
}

/* Bitumen Heating & Decanning rate (Rs / MT) - changeable from Settings tab */
var BIT_HEAT_VAL=137;
function updateBitHeat(){
  var inp=document.getElementById('sBitHeat');
  if(inp){var v=parseFloat(inp.value);BIT_HEAT_VAL=isNaN(v)?0:v;}
  updateAll();
}


/* ── DIFF. COST OF MATERIAL (tab 20) ─────────────────────────────────────
   Rows: {mat, ssr, mkt, rem}. Excess = mkt-ssr (if +ve), Less = ssr-mkt (if +ve). */
var DCM_ROWS=[];
function dcmNum(v){var n=parseFloat(v);return isNaN(n)?0:n;}
function dcmFillBit(r){
  var a=document.getElementById('sBitSSR'),b=document.getElementById('sBitCur');
  r.ssr=dcmNum(a&&a.value);r.mkt=dcmNum(b&&b.value);
}
function dcmAdd(name){
  var r={mat:name||'',ssr:0,mkt:0,rem:''};
  if(/bitumen/i.test(r.mat))dcmFillBit(r);
  DCM_ROWS.push(r);dcmRender();
}
function dcmPickAdd(sel){
  var v=sel.value;sel.value='';
  if(!v)return;
  dcmAdd(/^other/i.test(v)?'':v);
}
function dcmUpd(i,f,v){
  var r=DCM_ROWS[i];if(!r)return;
  if(f==='mat'||f==='rem')r[f]=v;else r[f]=dcmNum(v);
  if(f==='mat'&&/bitumen/i.test(v)&&!r.ssr&&!r.mkt)dcmFillBit(r);
  dcmRender();
}
function dcmDel(i){DCM_ROWS.splice(i,1);dcmRender();}
function dcmRender(){
  var tb=document.getElementById('dcmTb');if(!tb)return;
  /* Print All list: include this sheet only when it has rows */
  if(!DCM_ROWS.length){tb.innerHTML='<tr><td colspan="8" class="ni">Add a row</td></tr>';return;}
  var IN='border:1px solid #1565c0;border-radius:3px;background:#fff;font-size:.62rem;padding:.12rem .25rem;font-family:Arial,Helvetica,sans-serif;box-sizing:border-box;';
  var h='',i,r,ex,ls;
  for(i=0;i<DCM_ROWS.length;i++){
    r=DCM_ROWS[i];
    ex=r.mkt>r.ssr?Math.round((r.mkt-r.ssr)*100)/100:0;
    ls=r.ssr>r.mkt?Math.round((r.ssr-r.mkt)*100)/100:0;
    h+='<tr>'
      +'<td style="text-align:center">'+(i+1)+'</td>'
      +'<td><input class="noprt" type="text" value="'+_escER(r.mat)+'" placeholder="Material" onchange="dcmUpd('+i+',\'mat\',this.value)" style="'+IN+'width:100%">'
        +'<span class="prtonly">'+_escER(r.mat)+'</span></td>'
      +'<td class="r"><input class="noprt" type="number" step="any" value="'+(r.ssr||'')+'" placeholder="0" onchange="dcmUpd('+i+',\'ssr\',this.value)" style="'+IN+'width:96px;text-align:right">'
        +'<span class="prtonly">'+fmt(r.ssr)+'</span></td>'
      +'<td class="r"><input class="noprt" type="number" step="any" value="'+(r.mkt||'')+'" placeholder="0" onchange="dcmUpd('+i+',\'mkt\',this.value)" style="'+IN+'width:96px;text-align:right">'
        +'<span class="prtonly">'+fmt(r.mkt)+'</span></td>'
      +'<td class="r" style="font-family:Arial,Helvetica,sans-serif;font-variant-numeric:tabular-nums;font-weight:700;color:#2e7d32">'+fmt(ex)+'</td>'
      +'<td class="r" style="font-family:Arial,Helvetica,sans-serif;font-variant-numeric:tabular-nums;font-weight:700;color:#c62828">'+fmt(ls)+'</td>'
      +'<td><input class="noprt" type="text" value="'+_escER(r.rem)+'" placeholder="e.g. Ex-refinery Mumbai Rate As On 01.12.2023" onchange="dcmUpd('+i+',\'rem\',this.value)" style="'+IN+'width:100%">'
        +'<span class="prtonly">'+_escER(r.rem)+'</span></td>'
      +'<td class="noprt" style="text-align:center"><button onclick="dcmDel('+i+')" title="Delete row" style="background:#c62828;color:#fff;font-size:.52rem;padding:.12rem .3rem;border:none;border-radius:3px;cursor:pointer">\u2715</button></td>'
      +'</tr>';
  }
  tb.innerHTML=h;
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',dcmRender);else setTimeout(dcmRender,0);

/* Update custom SCADA value from settings input */
function updateScadaBt(){
  var inp=document.getElementById('sScadaBt');
  if(inp){var v=parseFloat(inp.value);if(!isNaN(v))CUSTOM_SCADA_BT=v;}
}
function updateScadaVal(){
  var inp=document.getElementById('sScadaVal');
  if(inp){
    var v=parseFloat(inp.value);
    if(!isNaN(v))CUSTOM_SCADA_VAL=v;
  }
}

