    +'<div style="font-size:.76rem;background:#fff4f4;border:1px solid #f0c4c4;border-radius:6px;padding:.45rem .6rem;max-height:150px;overflow:auto;margin-bottom:.8rem">'+list.map(function(x){return '<div>\u2022 '+x+'</div>';}).join('')+'</div>'
