/* Show the notice once an estimate has finished loading (local or cloud) */
(function royHideHookLoaders(){
  var tries=0;
  function hook(){
    var ok=true;
    if(typeof window.loadEst==='function'&&!window._royLoadEstHooked){
      var o1=window.loadEst;
      window.loadEst=function(){
        var before=items,args=arguments,self=this,n=0;
        var r=o1.apply(self,args);
        var iv=setInterval(function(){n++;if(items!==before){clearInterval(iv);setTimeout(royHideNotice,900);}if(n>40)clearInterval(iv);},300);
        return r;
      };
      window._royLoadEstHooked=true;
    }else if(!window._royLoadEstHooked)ok=false;
    if(typeof window.loadEstimate==='function'&&!window._royLoadEstimateHooked){
      var o2=window.loadEstimate;
      window.loadEstimate=function(){
        var r=o2.apply(this,arguments);
        setTimeout(royHideNotice,900);
        return r;
      };
      window._royLoadEstimateHooked=true;
    }
    return ok&&window._royLoadEstimateHooked;
  }
  if(!hook()){var iv=setInterval(function(){if(hook()||++tries>40)clearInterval(iv);},500);}
})();

