    +'</div></div>';
  document.body.appendChild(m);
  function chks(){return Array.prototype.slice.call(m.querySelectorAll('.pp-chk'));}
  function sync(){var n=chks().filter(function(c){return c.checked;}).length;var b=document.getElementById('ppGo');b.disabled=!n;b.style.opacity=n?'1':'.5';b.style.cursor=n?'pointer':'not-allowed';}
  chks().forEach(function(c){c.onchange=sync;});
  document.getElementById('ppAll').onclick=function(e){e.preventDefault();chks().forEach(function(c){c.checked=true;});sync();};
  document.getElementById('ppNone').onclick=function(e){e.preventDefault();chks().forEach(function(c){c.checked=false;});sync();};
