  wrap.innerHTML='<label style="display:flex;align-items:center;gap:.25rem;cursor:pointer"><input type="checkbox" id="sCessOn" onchange="updateAll()"'+(on?' checked':'')+'> Deduct / add Cess (surcharge on Net Basic)</label>'
    +'<input type="number" id="sCessPct" value="'+pc+'" step="0.01" min="0" max="100" onchange="updateAll()" oninput="updateAll()" style="width:52px;font-size:.62rem;padding:.15rem .25rem;border:1px solid #ddd;border-radius:3px"><span>%</span>'
    +'<label style="display:flex;align-items:center;gap:.25rem;cursor:pointer;flex-basis:100%" title="ON: SSR - Cess - SCADA = Net Rate; all % (Area/Floor/Add-on) are applied on it, and only Cess is added back at the end. OFF: old method (SCADA after %)"><input type="checkbox" id="sCessScada" onchange="updateAll()"'+(window.CESS_SCADA_FIRST!==false?' checked':'')+'> Deduct SCADA along with Cess (before the %)</label>';
