/* Save CF to HTML and download - CF permanently embedded */

/* ── SSR row layout (9 fields) ────────────────────────────────────────
   0 itemNo | 1 description | 2 unit | 3 rate | 4 additionalSpec
   5 srNo   | 6 chapter     | 7 refNo | 8 labourRate
   Fields 0-4 are the old layout - 5-8 are appended so existing code keeps working. */
var SSR_NCOL=9;
function ssrPad(d){d=d.slice();while(d.length<SSR_NCOL)d.push(d.length===8?0:'');return d;}
function ssrFromRow(row){
  var t=function(i){return row[i]==null?'':String(row[i]).trim();};
  return [t(0),t(1),uClean(t(2)),parseFloat(row[3])||0,t(4),(typeof row[5]==='number'?row[5]:t(5)),t(6),t(7),parseFloat(row[8])||0];
}
/* Firestore does not allow arrays inside arrays, so each chunk is stored as a JSON string.
   ssr_meta is written LAST so a half-failed save never leaves a broken meta behind. */
function ssrCloudWrite(ref,rows){
  var cs=400,chunks=[];
  for(var i=0;i<rows.length;i+=cs)chunks.push(rows.slice(i,i+cs));
  return Promise.all(chunks.map(function(c,ci){
    return ref.doc('ssr_chunk_'+ci).set({data:JSON.stringify(c),chunk:ci,fmt:'json'});
  })).then(function(){
    return ref.doc('ssr_meta').set({chunks:chunks.length,total:rows.length,fmt:'json',updatedAt:firebase.firestore.FieldValue.serverTimestamp()});
  }).then(function(){return chunks.length;});
}

function aSaveSSRCloud(){
  if(!window.firebase||!firebase.firestore){showToast("Firebase not ready","error");return;}
  if(!CU||CU.email!==ADMIN_EMAIL){showToast("Admin only","error");return;}
  normalizeUnits();var ssrData=SSR.map(ssrPad);
  showToast("Saving SSR to cloud...","info");
  ssrCloudWrite(firebase.firestore().collection("config"),ssrData).then(function(n){
    showToast("SSR saved to cloud! ("+ssrData.length+" items, "+n+" chunks)","success");
  }).catch(function(e){showToast("SSR save error: "+e.message,"error");});
}

function aSaveLeadCloud(){
  if(!window.firebase||!firebase.firestore){showToast("Firebase not ready","error");return;}
  if(!CU||CU.email!==ADMIN_EMAIL){showToast("Admin only","error");return;}
  /* Save full LL table to Firestore */
  var llData={};
  for(var k in LL){if(Array.isArray(LL[k]))llData[k]=LL[k];}
  showToast("Saving Lead Chart to cloud...","info");
  firebase.firestore().collection("config").doc("lead_ll").set({
    ll:llData,
    updatedAt:firebase.firestore.FieldValue.serverTimestamp(),
    updatedBy:CU.email
  }).then(function(){
    showToast("Lead Chart saved to cloud! All users will get the new rates on their next load.","success");
  }).catch(function(e){showToast("Lead save error: "+e.message,"error");});
}

