function addMR(){
  mrCount++;var id=mrCount;
  var div=document.createElement('div');div.className='mr';div.id='mr'+id;
  div.innerHTML='<input type="text" placeholder="Desc" id="ml'+id+'">'
    +'<select class="mfl" id="mf'+id+'" onchange="cMR('+id+')">'
    +flOpts(selSSR,FL_STD_FORM,0)
    +'</select>'
    +'<input type="number" placeholder="1" step="any" id="mn'+id
    +'" oninput="cMR('+id+')" value="1">'
    +'<input type="text" placeholder="L" id="ml2'+id+'" oninput="cMR('+id+')" style="font-family:Arial,Helvetica,sans-serif;width:55px">'
    +'<input type="text" placeholder="B" id="mb'+id+'" oninput="cMR('+id+')" style="font-family:Arial,Helvetica,sans-serif;width:55px">'
    +'<input type="text" placeholder="D/H" id="md'+id+'" oninput="cMR('+id+')" style="font-family:Arial,Helvetica,sans-serif;width:55px">'
    +'<span class="mt" id="mt'+id+'">0.000</span>'
    +'<button class="dr" onclick="this.parentElement.remove()">x</button>';
  R('measRows').appendChild(div);
}
function mrVal(id){
  var el=R(id);if(!el)return null;
  var v=el.value.trim();
  if(v==="")return null;
  if(v.charAt(0)==="="){
    try{
      /* Support =N.L (row 0) and =N.rL (row r, 0-based) e.g. =1.0L =2.1B */
      var expr=v.substring(1).replace(/(\d+)\.(\d+)(L|B|D|H|N)/gi,function(mm,ino,rno,fld){
        var it=items[parseInt(ino)-1];
        var rIdx=parseInt(rno);
        /* skip isTot rows when resolving */
        var realRows=(it&&it.rows)?it.rows.filter(function(r){return !r.isTot;}):[];
        var row=realRows[rIdx];
        if(!row)return '0';
        var f=fld.toUpperCase();
        var val=f==='L'?row.l:f==='B'?row.b:f==='D'||f==='H'?row.d:row.n;
        return String(val||0);
      }).replace(/(\d+)\.(L|B|D|H|N)/gi,function(mm,ino,fld){
        /* =N.L shorthand = row 0 of item N */
        var it=items[parseInt(ino)-1];
        var realRows=(it&&it.rows)?it.rows.filter(function(r){return !r.isTot;}):[];
        var row=realRows[0];
        if(!row)return '0';
        var f=fld.toUpperCase();
        var val=f==='L'?row.l:f==='B'?row.b:f==='D'||f==='H'?row.d:row.n;
        return String(val||0);
      });
      var res=Function("\"use strict\";return ("+expr+")")();
      el.style.background=isNaN(res)?"#ffebee":"#e8f5e9";
      return isNaN(res)?null:res;
    }catch(e){el.style.background="#ffebee";return null;}
  }
  el.style.background="";
  var num=parseFloat(v);
  return isNaN(num)?null:num;
}
function cMR(id){
  var n=pf("mn"+id)||1;
  var lv=mrVal("ml2"+id),bv=mrVal("mb"+id),dv=mrVal("md"+id);
  var t=n;
  if(lv!==null&&lv!==0)t*=lv;
  if(bv!==null&&bv!==0)t*=bv;
  if(dv!==null&&dv!==0)t*=dv;
  var el=R("mt"+id);if(el)el.textContent=t.toFixed(3);
}
function addToEst(){
  if(!selSSR)return;
  var rows=[],qty=0,amount=0,allMr,i,id,n,l,b,dv,lbl,q,fl,flPct,flRate;
  var cf=selSSR.cf||{},sv=selSSR.scadaVal||0;
  var res=calcItemLead(cf);
  var baseRate=selSSR.rate+res.total+sv;
  allMr=document.querySelectorAll('[id^="mr"]');
  for(i=0;i<allMr.length;i++){
    id=allMr[i].id.replace('mr','');if(!R('mn'+id))continue;
    n=pf('mn'+id)||1;
    var _lv=mrVal('ml2'+id),_bv=mrVal('mb'+id),_dv=mrVal('md'+id);
    l=_lv!==null?_lv:0;b=_bv!==null?_bv:0;dv=_dv!==null?_dv:0;
    lbl=((R('ml'+id)||{}).value||'');
    fl=parseInt((R('mf'+id)||{}).value||'0');
    flRate=flRateOf({desc:selSSR.desc,baseRate:selSSR.rate,scadaVal:sv},fl,baseRate);
    q=n;
    if(_lv!==null&&_lv!==0)q*=_lv;
    if(_bv!==null&&_bv!==0)q*=_bv;
    if(_dv!==null&&_dv!==0)q*=_dv;
    if(q>0){
      rows.push({lbl:lbl,n:n,l:l,b:b,d:dv,qty:q,fl:fl,flRate:flRate});
      qty+=q;amount+=flRate*q;
    }
  }
  if(qty<=0){alert('Quantity is 0. Enter measurements.');return;}
  qty=Math.round(qty*1000)/1000;
  amount=Math.round(amount*100)/100;
  var fr=Math.round(baseRate*100)/100;
  var existIdx=-1,k;
  for(k=0;k<items.length;k++){if(items[k].no===selSSR.no){existIdx=k;break;}}
  if(existIdx>=0){
    var ex=items[existIdx];ex.rows=ex.rows.concat(rows);
    ex.qty=Math.round((ex.qty+qty)*1000)/1000;
    ex.amount=Math.round((ex.amount+amount)*100)/100;items[existIdx]=ex;
  } else {
    items.push({id:Date.now(),no:selSSR.no,desc:selSSR.desc,unit:selSSR.unit,spec:selSSR.spec||'',
      baseRate:selSSR.rate,cf:cf,scadaVal:sv,
      leadPerUnit:Math.round(res.total*100)/100,leadMats:res.mats,
      finalRate:fr,qty:qty,rows:rows,amount:amount});
    atpPlaceLastAtInsertPos();
  }
  closeForm();updateAll();
}
function closeForm(){R('addForm').classList.remove('on');selSSR=null;}
function removeItem(id){
  var d=-1,k;
  for(k=0;k<items.length;k++){if(items[k].id===id){d=k;break;}}
  if(d>=0)atpDeleteItemAt(d);
  updateAll();
}

/* ── ROYALTY & GRAND ─────────────────────────────────────────────────── */
/* Single source of truth for royalty (Royalty Statement, Recapitulation, Grand total all use this).
   Per item: net qty rounded to 3 decimals, then royalty rounded to whole rupees, then summed. */
function _royTotals(S){
  var rS=0,rC=0,i,cf,sF,cF,nS,nC;
  for(i=0;i<items.length;i++){
    cf=effCF(items[i]);
    sF=(cf.scr_sand||0)+(cf.sand||0)+(cf.quarry||0);
    cF=royCoarseF(cf,items[i]);
    nS=Math.round(sF*items[i].qty*1000)/1000;
    nC=Math.round(cF*items[i].qty*1000)/1000;
    rS+=Math.round(nS*S.royS);
    rC+=Math.round(nC*S.royC);
  }
  return {rS:rS,rC:rC};
}
function calcRoyTotal(S){
  var r=_royTotals(S);
  return r.rS+r.rC;
}
function calcGrand(){
  var S=gS(),A=0,i;
  for(i=0;i<items.length;i++)A+=items[i].amount;A=Math.round(A);
  var roy=Math.round(calcRoyTotal(S));
  var mtf=Math.round(window._mtfTotalVal||0);
  var ABC=A+roy+mtf;
  var specF=0; /* Area % now included in each item's finalRate — not added separately */
  var extraTotal=0;if(S.extraRows&&S.extraRows.length){for(var _ei=0;_ei<S.extraRows.length;_ei++){if(extraOn(S.extraRows[_ei]))extraTotal+=extraAmt(A,S.extraRows[_ei]);}}
  return ABC+Math.round(gstBaseAmt(A,ABC)*S.gst/100)+contAmt(A,S)+Math.round(A*liEff(A,S)/100)+specF+extraTotal;
}

function msrResolve(v,iIdx){
  if(v===""||v===null)return null;
  v=String(v).trim();
  if(v.charAt(0)==="="){
    try{
      /* Step 1: resolve =N.rL (item N, row r, field L) e.g. =1.0L */
      var expr=v.substring(1).replace(/(\d+)\.(\d+)(L|B|D|H|N)/gi,function(mm,ino,rno,fld){
        var it=items[parseInt(ino)-1];
        var rIdx=parseInt(rno);
        var realRows=(it&&it.rows)?it.rows.filter(function(r){return !r.isTot;}):[];
        var row=realRows[rIdx];
        if(!row)return '0';
        var f=fld.toUpperCase();
        return String((f==='L'?row.l:f==='B'?row.b:f==='D'||f==='H'?row.d:row.n)||0);
      });
      /* Step 2: resolve =N.L (item N, row 0, field L) */
      expr=expr.replace(/(\d+)\.(L|B|D|H|N)/gi,function(mm,ino,fld){
        var it=items[parseInt(ino)-1];
        var realRows=(it&&it.rows)?it.rows.filter(function(r){return !r.isTot;}):[];
        var row=realRows[0];
        if(!row)return '0';
        var f=fld.toUpperCase();
        return String((f==='L'?row.l:f==='B'?row.b:f==='D'||f==='H'?row.d:row.n)||0);
      });
      var res=Function("\"use strict\";return ("+expr+")")();
      return isNaN(res)?null:res;
    }catch(e){return null;}
  }
  var num=parseFloat(v);
  return isNaN(num)?null:num;
}
function msrUpd(iIdx,rIdx,el,field){
  var it=items[iIdx];if(!it||!it.rows||!it.rows[rIdx])return;
  var r=it.rows[rIdx];
  if(!r._f)r._f={};
  if(field==="lbl"){r.lbl=el.value;return;}
  else if(r.isPct){
    if(field==="pct"){r.pct=parseFloat(el.value)||0;r.factor=msrPctRound(r.pct/100);}
    else if(field==="factor"){r.factor=parseFloat(el.value)||0;r.pct=msrPctRound(r.factor*100);}
    else if(field==="pctMode"){
      /* % <-> Factor toggle — also works on rows of old estimates; qty stays the same */
      if(el.value==="factor"){r.factor=msrPctRound(msrPctFactorVal(r));r.pctMode="factor";}
      else{r.pct=msrPctRound(msrPctFactorVal(r)*100);r.pctMode="pct";}
      msrSyncAllRows();
      for(var _mi=0;_mi<items.length;_mi++)items[_mi]=recalcItem(items[_mi]);
      rMS();updateAll();
      return;
    }
    else if(field==="pctSrc")r.pctSrc=(el.value==="self")?"self":parseInt(el.value,10);
  }
  else if(field==="n"){
    var rawN=String(el.value).trim();
    if(rawN.charAt(0)==="="){
      var vN=msrResolve(rawN,iIdx);
      if(vN!==null){r._f.n=rawN;r.n=vN||1;el.style.background="#e8f5e9";}
      else{el.style.background="#ffebee";return;}
    }else{delete r._f.n;el.style.background="";r.n=parseFloat(rawN)||1;}
  }
  else if(!r.isPct){
    var raw=el.value.trim();
    /* avg(a,b,...) shorthand → (a+b+...)/n */
    if(/^avg\s*\(/i.test(raw)){
      var nums=raw.replace(/^avg\s*\(/i,'').replace(/\)\s*$/,'').split(',');
      var sum=0,cnt=0;
      nums.forEach(function(x){var v=parseFloat(x.trim());if(!isNaN(v)){sum+=v;cnt++;}});
      if(cnt>0){el.value=String(Math.round(sum/cnt*1000)/1000);raw=el.value;}
    }
    var isF=raw.charAt(0)==="=";
    if(isF){
      var v=msrResolve(raw,iIdx);
      if(v!==null){
        r._f[field]=raw;   /* store formula */
        r[field]=v;
        el.style.background="#e8f5e9";
      } else {
        el.style.background="#ffebee";
        return; /* incomplete formula - dont update */
      }
    } else {
      delete r._f[field];  /* clear formula if plain value */
      /* Link preserved — edit source row to change linked values */
      el.style.background="";
      var num=raw===""?null:parseFloat(raw);
      r[field]=(raw===""||isNaN(num))?null:num;
    }
  }
  /* Recalc — this item, every linked row, every % row, then Abstract */
  msrSyncAllRows();
  for(var _ai=0;_ai<items.length;_ai++)items[_ai]=recalcItem(items[_ai]);
  msrRefreshAllDisplays();
  clearTimeout(window._uaT);window._uaT=setTimeout(_doUpdateAllNoMS,300);
}
/* ══ FLOOR GROUPING ═════════════════════════════════════════════════
   An item's rows are always grouped floor-wise: G, then 1st, 2nd ... (within a group
   in the order they were added). When a row's floor changes, it moves into its own floor's group.
   When a row moves, linked rows (_linkedFrom) and formulas (=1.2L) get their row numbers updated. */
function msrLastFloor(it){
  if(!it||!it.rows)return 0;
  for(var k=it.rows.length-1;k>=0;k--){var r=it.rows[k];if(r&&!r.isTot)return r.fl!=null?r.fl:0;}
  return 0;
}
function msrRemapRefs(iIdx,rawFn,realFn){
  items.forEach(function(oi){
    (oi.rows||[]).forEach(function(r){
      if(r._linkedFrom&&r._linkedFrom.iIdx===iIdx){
        var n=rawFn(r._linkedFrom.rIdx);
        if(n<0)delete r._linkedFrom;else r._linkedFrom.rIdx=n;
      }
      if(r._f){
        Object.keys(r._f).forEach(function(k){
          var v=r._f[k];if(typeof v!=='string'||v.charAt(0)!=='=')return;
          r._f[k]=v.replace(/(\d+)\.(\d*)(L|B|D|H|N)/gi,function(mm,ino,rno,fld){
            if(parseInt(ino,10)-1!==iIdx)return mm;
            var old=(rno==='')?0:parseInt(rno,10);
            var nw=realFn(old);
            if(nw<0)return '0';
            if(rno===''&&nw===0)return mm;
            return ino+'.'+nw+fld;
          });
        });
      }
    });
  });
}
function msrRegroupItem(iIdx){
  var it=items[iIdx];if(!it||!it.rows)return false;
  var rows=it.rows;
  /* a row whose floor changed (_moved) goes to the end of the new group — "shift down" */
  var arr=rows.map(function(r,k){return {r:r,k:k,o:(r&&r._moved)?1e5+k:k,key:(r&&r.isTot)?1e6:((r&&parseInt(r.fl,10))||0)};});
  rows.forEach(function(r){if(r&&r._moved)delete r._moved;});
  if(rows.length<2)return false;
  arr.sort(function(a,b){return (a.key-b.key)||(a.o-b.o);});
  var changed=false,i;
  for(i=0;i<arr.length;i++){if(arr[i].k!==i){changed=true;break;}}
  if(!changed)return false;
  var rawMap={},oldReal={},newReal={},realMap={},c=0;
  arr.forEach(function(a,ni){rawMap[a.k]=ni;});
  rows.forEach(function(r,k){if(!r.isTot){oldReal[k]=c++;}});
  c=0;arr.forEach(function(a,ni){if(!a.r.isTot){newReal[ni]=c++;}});
  Object.keys(oldReal).forEach(function(k){realMap[oldReal[k]]=newReal[rawMap[k]];});
  it.rows=arr.map(function(a){return a.r;});
  msrRemapRefs(iIdx,function(o){return rawMap[o]!=null?rawMap[o]:o;},function(o){return realMap[o]!=null?realMap[o]:o;});
  window._msrSel={};
  return true;
}
function msrRegroupAll(){for(var g=0;g<items.length;g++)msrRegroupItem(g);}
/* Floor cell — floor label only on the first row of the group; the dropdown on the other rows is faded */
var GF_CUR=null;   /* current item in rMS — so msrFloorCell knows about Only Ground Floor mode */
function msrFloorCell(selHtml,grpFirst,fcls,flbl){
  if(grpFirst){
    var _gfB=(GF_CUR&&gfOff(GF_CUR))?'':'<span class="prtonly fl-badge '+fcls+'" style="font-size:9.5pt!important;line-height:1.2;font-family:Arial,Helvetica,sans-serif!important">'+flbl+'</span>';   /* Only Ground Floor ON: "G" is not shown in print */
    return '<td style="text-align:left">'+selHtml+_gfB+'</td>';
  }
  return '<td style="text-align:left"><span class="noprt" style="opacity:.3" onmouseover="this.style.opacity=1" onmouseout="this.style.opacity=.3" onfocusin="this.style.opacity=1" onfocusout="this.style.opacity=.3" title="To change the floor, select it here">'+selHtml+'</span></td>';
}
function msrSetFloor(iIdx,rIdx,val){
  var it=items[iIdx];if(!it||!it.rows||!it.rows[rIdx])return;
  var _nf=parseInt(val,10)||0;
  if(it.rows[rIdx].fl!==_nf){it.rows[rIdx].fl=_nf;it.rows[rIdx]._moved=true;}
  rMS();updateAll();
}
function editMeasRow(iIdx,rIdx){
  var el=document.querySelector("#msr_"+iIdx+"_"+rIdx+" input");
  if(el)el.focus();
}

function delMeasRow(itemIdx,rowIdx){
  var it=items[itemIdx];
  if(!it||!it.rows||!it.rows[rowIdx])return;
  if(!confirm('Delete this measurement row?'))return;
  var _realDel=-1,_rc=0;
  it.rows.forEach(function(rw,k){if(!rw.isTot){if(k===rowIdx)_realDel=_rc;_rc++;}});
  it.rows.splice(rowIdx,1);
  if(it.meas&&it.meas[rowIdx])it.meas.splice(rowIdx,1);
  /* rows linked to this item's rows and formulas (=1.2L) — shift row numbers / unlink */
  msrRemapRefs(itemIdx,
    function(o){return o===rowIdx?-1:(o>rowIdx?o-1:o);},
    function(o){return _realDel<0?o:(o===_realDel?-1:(o>_realDel?o-1:o));});
  /* Recalc total (includes % rows) */
  msrRecalcItem(itemIdx);
  if(it.rows.length===0){
    /* Remove item if no rows */
    if(confirm('No measurements left. Remove item?')){
      atpDeleteItemAt(itemIdx);
    }
  }else{
    items[itemIdx]=recalcItem(it);
  }
  updateAll();
}

