/* Add the selected SSR item straight into the estimate with one blank row,
   jump to the Measurement Sheet tab and focus that row. */
function atpAddSelDirect(){
  if(!selSSR)return;
  var cf=selSSR.cf||{},sv=selSSR.scadaVal||0;
  var res=calcItemLead(cf);
  var baseRate=selSSR.rate+res.total+sv;
  var fr=Math.round(baseRate*100)/100;
  var blank={lbl:'',n:1,l:0,b:0,d:0,qty:0,fl:0,flRate:fr};
  var existIdx=-1,k;
  for(k=0;k<items.length;k++){if(items[k].no===selSSR.no){existIdx=k;break;}}
  var tIdx,rIdx;
  if(existIdx>=0){
    var ex=items[existIdx];
    if(!ex.rows)ex.rows=[];
    var ti=ex.rows.findIndex(function(r){return r.isTot;});
    if(ti>=0){ex.rows.splice(ti,0,blank);rIdx=ti;}
    else{ex.rows.push(blank);rIdx=ex.rows.length-1;}
    tIdx=existIdx;
  } else {
    items.push({id:Date.now(),no:selSSR.no,desc:selSSR.desc,unit:selSSR.unit,spec:selSSR.spec||'',
      baseRate:selSSR.rate,cf:cf,scadaVal:sv,
      leadPerUnit:Math.round(res.total*100)/100,leadMats:res.mats,
      finalRate:fr,qty:0,rows:[blank],amount:0});
    tIdx=items.length-1;rIdx=0;
    tIdx=atpPlaceLastAtInsertPos();
  }
  closeForm();
  updateAll();
  if(typeof goTab==='function')goTab(5);
  setTimeout(function(){
    var _bi=(items[tIdx]&&items[tIdx].rows)?items[tIdx].rows.indexOf(blank):-1;
    if(_bi>=0)rIdx=_bi;   /* row index after grouping */
    var row=R('msr_'+tIdx+'_'+rIdx);
    if(!row)return;
    row.scrollIntoView({behavior:'smooth',block:'center'});
    var ob=row.style.background;
    row.style.background='#fff3cd';
    setTimeout(function(){row.style.background=ob;},1500);
    var inps=row.querySelectorAll('input');
    if(inps&&inps.length)inps[0].focus();
  },260);
  if(typeof showToast==='function')showToast('Item added — enter L / B / D here','success');
}
