function msrPasteRows(destIIdx){
  var keys=Object.keys(window._msrSel);
  if(!keys.length){alert('No rows selected. Please check at least one row.');return;}
  var destIt=items[destIIdx];
  if(!destIt||!destIt.rows){return;}

  var selList=keys.map(function(k){return window._msrSel[k];});
  selList.sort(function(a,b){return a.iIdx!==b.iIdx?a.iIdx-b.iIdx:a.rIdx-b.rIdx;});

  /* Which fields to keep LIVE-linked — user's choice via checkboxes (default L+B) */
  var _lf=window._msrLinkFields||{n:false,l:true,b:true,d:false,qty:false};
  var _linkedFieldList=['n','l','b','d','qty'].filter(function(f){return _lf[f];});
  if(_lf.qty)_linkedFieldList=['qty'];  /* whole-row Qty link */
  if(!_linkedFieldList.length){alert('Please select at least one field (N/L/B/D/Qty) to link.');return;}
  var _linkPct=parseFloat(window._msrLinkPct);if(isNaN(_linkPct)||_linkPct<=0)_linkPct=100;

  selList.forEach(function(src){
    var srcIt=items[src.iIdx];
    if(!srcIt||!srcIt.rows||!srcIt.rows[src.rIdx])return;
    var srcR=srcIt.rows[src.rIdx];

    /* Store index-based reference to source row — JSON-safe, recalc-safe */
    /* Fields NOT chosen for linking are copied once but stay independent/editable */
    var newRow={
      lbl:      srcR.lbl||'',
      n:        srcR.n||1,
      l:        srcR.l||0,
      b:        srcR.b||0,
      d:        srcR.d||0,
      qty:      0,
      fl:       srcR.fl||0,
      isDeduct: srcR.isDeduct||false,   /* preserve deduction flag */
      _linkedFrom: {iIdx: src.iIdx, rIdx: src.rIdx, fields: _linkedFieldList.slice(), pct: _linkPct}  /* index ref — survives JSON save/load */
    };
    if(_lf.qty){
      newRow.qty=Math.round((srcR.qty||0)*_linkPct/100*1000)/1000;
    } else {
      var _t=(newRow.n||1);
      if(newRow.l)_t*=newRow.l; if(newRow.b)_t*=newRow.b; if(newRow.d)_t*=newRow.d;
      newRow.qty=(newRow.isDeduct?-1:1)*Math.round(_t*1000)/1000;
    }
    /* Insert before any isTot / % row so % rows stay at the bottom */
    var _ti=destIt.rows.findIndex(function(r){return r.isTot;});
    if(_ti>=0) destIt.rows.splice(_ti,0,newRow);
    else destIt.rows.push(newRow);
  });

  msrRecalcItem(destIIdx);
  items[destIIdx]=recalcItem(destIt);

  window._msrSel={};
  window._msrSelActive=false;
  rMS();
  updateAll();
  if(typeof showToast==='function') showToast(selList.length+' row(s) pasted — '+_linkedFieldList.map(function(f){return f.toUpperCase();}).join('+')+' linked live, rest independent.','success');
}

