        +'<td class="r" style="font-size:.62rem"><b id="mstot_'+i+'">'+it.qty.toFixed(3)+'</b></td>'
        +'<td style="font-size:.62rem"><b>'+unitShort(it.unit)+'</b></td>'
        +'<td class="noprt"></td></tr>';
