  var gst=Math.round(gstBaseAmt(A,ABC)*S.gst/100),cont=contAmt(A,S),li=Math.round(A*liEff(A,S)/100);
  var specF=0; /* Area % now included in each item's finalRate — not added separately */
  var extraTotalFE=0;if(S.extraRows&&S.extraRows.length){for(var _eife=0;_eife<S.extraRows.length;_eife++){if(extraOn(S.extraRows[_eife]))extraTotalFE+=extraAmt(A,S.extraRows[_eife]);}}
