  var extraTotal2=0;var S2=gS();if(S2.extraRows&&S2.extraRows.length){for(var _ei3=0;_ei3<S2.extraRows.length;_ei3++){if(extraOn(S2.extraRows[_ei3]))extraTotal2+=extraAmt(A,S2.extraRows[_ei3]);}}
