/* Qty display: small values (e.g. steel in MT) must not show as 0.00 */
function _mtfFmtQty(v){
  v=+v||0;
  if(v===0)return '0.00';
  if(Math.abs(v)>=1)return v.toFixed(2);
  var s=v.toFixed(3);
  return (+s===0)?v.toPrecision(2):s;
}
/* Print: renumber visible (non-zero) rows 1,2,3... without gaps */
window.addEventListener('beforeprint',function(){
  var n=0;
  document.querySelectorAll('#mtfTb tr').forEach(function(tr){
    if(tr.classList.contains('mtf-zero'))return;
    var sp=tr.querySelector('.mtf-sr');if(sp)sp.textContent=(++n);
  });
});
window.addEventListener('afterprint',function(){
  document.querySelectorAll('#mtfTb .mtf-sr').forEach(function(sp){sp.textContent=sp.getAttribute('data-sr');});
});

function resetMTF(){
  /* Clear all manual overrides so auto-calc runs fresh */
  mtfData.forEach(function(row){delete row._qty;delete row._tests;});MTF_CONC_Q={};MTF_CONC_T={};MTF_PICK.forEach(function(p){delete p.q;delete p.t;});
  calcMTF();
}/* ══ CEMENT CONCRETE — grade-wise rows in Testing tab ═══════════════════
   The estimate's concrete items (Cu.M.) are split into separate rows by grade.
   For each grade: "Cement Concrete - M-10" => its qty => its cube sets.
   Items are detected automatically, but the user is shown them and asked "is this correct?";
   if something is wrong, change the item's grade from its dropdown. Cost/Test is the same for all rows.
   ═══════════════════════════════════════════════════════════════════════ */
var MTF_GRADES=['M-5','M-7.5','M-10','M-15','M-20','M-25','M-30','M-35','M-40'];
var MTF_CONC_MAP={};  /* itemKey -> 'M-10' | 'none'  (user override) */
var MTF_CONC_OK='';   /* signature of the mapping the user has confirmed */
var MTF_CONC_Q={};    /* grade -> manual qty */
var MTF_CONC_T={};    /* grade -> manual tests (sets) */
function _mcEsc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function mtfItemKey(it){return String(it.id!=null?it.id:('n'+it.no));}
/* Nominal mix ratio (IS 456) -> grade, e.g. 1:3:6 -> M-10 (user can still change in the dropdown) */
function mtfRatioGrade(desc){
  var m=/(\d+(?:\.\d+)?)\s*:\s*(\d+(?:\.\d+)?)\s*:\s*(\d+(?:\.\d+)?)/.exec(desc||'');
  if(!m||!(+m[1]>0))return null;
  var k='1:'+(+m[2]/+m[1])+':'+(+m[3]/+m[1]);
  var map={'1:5:10':'M-5','1:4:8':'M-7.5','1:3:6':'M-10','1:2:4':'M-15','1:1.5:3':'M-20','1:1:2':'M-25'};
  return map[k]||null;
}
function mtfConcCands(){
  var out=[];
  (items||[]).forEach(function(it,idx){
    var d=it.desc||'';
    if(!/concrete|\bR\.?\s?C\.?\s?C\b|\bP\.?\s?C\.?\s?C\b/i.test(d)||!/cu[a-z]*\.?\s*m|m3|m\u00B3/i.test(it.unit||''))return;
    out.push({it:it,idx:idx,key:mtfItemKey(it),auto:(trGradeOf(d)||mtfRatioGrade(d)||'none')});
  });
  return out;
}
function mtfConcEff(){
  var cands=mtfConcCands(),by={},order=[],none=[];
  cands.forEach(function(c){
    var g=(MTF_CONC_MAP[c.key]!==undefined)?MTF_CONC_MAP[c.key]:c.auto;
    c.g=g;
    if(g==='none'){none.push(c);return;}
    if(!by[g]){by[g]={grade:g,items:[],raw:0};order.push(g);}
    by[g].items.push(c);by[g].raw+=(+c.it.qty||0);
  });
  order.sort(function(a,b){return parseFloat(a.slice(2))-parseFloat(b.slice(2));});
  var grades=order.map(function(g){
    var o=by[g];
    o.qtyAuto=Math.round(o.raw*100)/100;
    o.qty=(MTF_CONC_Q[g]!==undefined)?MTF_CONC_Q[g]:o.qtyAuto;
    o.setsAuto=trCubeSets(o.qty);
    o.tests=(MTF_CONC_T[g]!==undefined)?MTF_CONC_T[g]:o.setsAuto;
    return o;
  });
  var sig=JSON.stringify(grades.map(function(g){return [g.grade,g.items.map(function(c){return c.key;}).sort()];}));
  return {grades:grades,none:none,cands:cands,sig:sig};
}
function mtfConcForSave(){return {map:MTF_CONC_MAP,ok:MTF_CONC_OK,q:MTF_CONC_Q,t:MTF_CONC_T,x:mtfXForSave()};}
function mtfConcRestore(o){
  MTF_CONC_MAP=(o&&o.map)?JSON.parse(JSON.stringify(o.map)):{};
  MTF_CONC_OK=(o&&o.ok)||'';
  MTF_CONC_Q=(o&&o.q)?JSON.parse(JSON.stringify(o.q)):{};
  MTF_CONC_T=(o&&o.t)?JSON.parse(JSON.stringify(o.t)):{};
  mtfXRestore(o);
  if(typeof calcMTF==='function')calcMTF();
}
function mtfConcSet(key,g){MTF_CONC_MAP[key]=g;calcMTF();_refreshGrand();}
function mtfConcConfirm(){MTF_CONC_OK=mtfConcEff().sig;calcMTF();if(typeof showToast==='function')showToast('\u2705 Concrete grade items confirmed','success');}
function mtfConcQty(g,v){MTF_CONC_Q[g]=parseFloat(v)||0;calcMTF();_refreshGrand();}
function mtfConcTests(g,v){MTF_CONC_T[g]=Math.max(0,parseInt(v)||0);calcMTF();_refreshGrand();}

function renderMTFConcBox(conc){
  var box=G('mtfConcBox');if(!box)return;
  if(!conc.cands.length){
    var _mt={cement:0,aggregate:0};try{_mt=getMaterialTotals();}catch(e){}
    if(_mt.cement>0||_mt.aggregate>0){
      box.style.display='block';
      box.innerHTML='<div style="border:1px solid #ffb74d;background:#fff8e1;border-radius:8px;padding:.45rem .7rem;margin-bottom:.7rem;font-size:.62rem;line-height:1.5">\u26A0\uFE0F No concrete (Cu.M.) item found in the estimate, so cube tests are 0. The item description must contain <b>concrete / PCC / RCC</b> and the unit must be <b>Cu.M.</b></div>';
    }else{box.style.display='none';box.innerHTML='';}
    return;
  }
  box.style.display='block';
  var ok=(MTF_CONC_OK===conc.sig&&conc.grades.length>0);
  function opts(sel){
    var h='<option value="none"'+(sel==='none'?' selected':'')+'>\u2014 no cube test \u2014</option>';
    var list=MTF_GRADES.slice();if(sel!=='none'&&list.indexOf(sel)<0)list.push(sel);
    list.forEach(function(g){h+='<option value="'+g+'"'+(g===sel?' selected':'')+'>'+g+'</option>';});
    return h;
  }
  function rowHtml(c){
    var d=String(c.it.desc||'').replace(/\s+/g,' ');if(d.length>120)d=d.slice(0,117)+'\u2026';
    return '<tr><td style="white-space:nowrap">#'+(c.idx+1)+(c.it.no?' <span style="color:#888">('+_mcEsc(c.it.no)+')</span>':'')+'</td>'
      +'<td>'+_mcEsc(d)+'</td><td style="text-align:right;white-space:nowrap">'+(Math.round((+c.it.qty||0)*100)/100)+' '+_mcEsc(c.it.unit||'')+'</td>'
      +'<td><select onchange="mtfConcSet(\''+c.key.replace(/'/g,"\\'")+'\',this.value)" style="font-size:.62rem;padding:.15rem;border:1px solid #bbb;border-radius:4px">'+opts(c.g)+'</select></td></tr>';
  }
  var h='<div style="border:1px solid '+(ok?'#81c784':'#ffb74d')+';background:'+(ok?'#f1f8e9':'#fff8e1')+';border-radius:8px;padding:.55rem .7rem;margin-bottom:.7rem;font-size:.62rem;line-height:1.5">';
  h+='<div style="font-weight:800;font-size:.7rem;color:#1a237e;margin-bottom:.25rem">\uD83E\uDDF1 Cement Concrete \u2014 items by grade (for cube tests)</div>';
  if(ok){
    h+='<div style="color:#2e7d32;font-weight:700;margin-bottom:.3rem">\u2705 Confirmed. If the items / grades change, you will be asked again.</div>';
  }else{
    h+='<div style="color:#bf360c;margin-bottom:.35rem">\u26A0\uFE0F Items have been picked automatically by grade. <b>Please check that the items listed under each grade are correct.</b> '
      +'If anything is wrong, change the item\'s grade from its dropdown (or choose "no cube test"). If everything is correct, press <b>\u2714 Looks correct</b>.</div>';
  }
  h+='<table style="width:100%;border-collapse:collapse;font-size:.6rem"><thead><tr style="background:#eee"><th style="text-align:left;padding:.2rem .3rem">Item</th><th style="text-align:left">Description</th><th style="text-align:right">Qty</th><th style="text-align:left">Grade</th></tr></thead><tbody>';
  conc.grades.forEach(function(g){
    h+='<tr style="background:#e3f2fd"><td colspan="4" style="padding:.25rem .3rem;font-weight:800">'+g.grade+' &nbsp;\u2192&nbsp; '+g.items.length+' item(s) &nbsp;|&nbsp; Total qty = '+g.qty+' Cu.M. &nbsp;|&nbsp; Cube tests = '+g.tests+' set'+(g.tests===1?'':'s')+'</td></tr>';
    g.items.forEach(function(c){h+=rowHtml(c);});
  });
  if(conc.none.length){
    h+='<tr style="background:#f5f5f5"><td colspan="4" style="padding:.25rem .3rem;font-weight:800;color:#666">Not taken for cube test (grade not found / not selected)</td></tr>';
    conc.none.forEach(function(c){h+=rowHtml(c);});
  }
  h+='</tbody></table>';
  if(!ok&&conc.grades.length){
    h+='<div style="margin-top:.45rem"><button onclick="mtfConcConfirm()" style="background:#2e7d32;color:#fff;border:none;border-radius:6px;padding:.35rem .9rem;font-size:.68rem;font-weight:700;cursor:pointer">\u2714 Looks correct</button></div>';
  }
  h+='</div>';
  box.innerHTML=h;
}

function mtfEffRows(mats){
  var out=[],conc=mtfConcEff();
  mtfData.forEach(function(row){
    if(row.sr===4&&!row.isCustom){
      if(conc.grades.length){
        conc.grades.forEach(function(g,i){out.push({row:row,g:g,label:'4.'+(i+1),qty:g.qty,tests:g.tests,cost:row.cost||0});});
      }else{
        out.push({row:row,g:null,label:'4',qty:0,tests:0,cost:row.cost||0});
      }
      return;
    }
    var qty=0;
    if(row._qty!==undefined&&row._qty!==null){
      qty=row._qty;
    }else if(row.qtyFormula){
      try{
        qty=eval(row.qtyFormula.replace('cement',mats.cement||0)
          .replace('aggregate',mats.aggregate||0)
          .replace('sand',mats.sand||0)
          .replace('steel',mats.steel||0)
          .replace('bricks',mats.bricks||0));
      }catch(e){qty=0;}
    }
    qty=qty||0;
    var tests=0;
    if(row._tests!==undefined&&row._tests!==null){tests=row._tests;}
    else{tests=(row.threshold>0&&qty>0)?Math.ceil(qty/row.threshold):((qty>0&&row.threshold===0)?1:0);}
    out.push({row:row,g:null,label:String(row.sr),qty:qty,tests:tests,cost:row.cost||0});
  });
  return {rows:out,conc:conc};
}

function calcMTF(){
  var mats=getMaterialTotals();
  var eff=mtfEffRows(mats),tot=0;
  eff.rows.forEach(function(e){tot+=e.tests*e.cost+mtfMixCost(e);});tot+=mtfPickTotal();
  window._mtfTotalVal=Math.round(tot);
  if(R('mtfTotal'))R('mtfTotal').textContent=tot.toFixed(2);

  var tb=R('mtfTb');if(!tb)return;
  var h='';
  eff.rows.forEach(function(e){
    var row=e.row,qty=e.qty,tests=e.tests,costPerTest=e.cost,totalCost=tests*costPerTest+mtfMixCost(e);
    var virt=!!e.g,isConcRow=(row.sr===4&&!row.isCustom);
    h+=(totalCost===0&&qty===0)?'<tr class="mtf-zero">':'<tr>';
    if(row.isCustom){
      h+='<td style="font-size:.57rem;white-space:nowrap"><button class="noprt" onclick="removeMTFRow('+row.sr+')" style="background:#c0392b;color:#fff;border:none;border-radius:4px;padding:.1rem .35rem;font-size:.55rem;cursor:pointer;margin-right:.25rem">🗑</button><span class="mtf-sr" data-sr="'+row.sr+'">'+row.sr+'</span></td>';
    }else{
      h+='<td style="font-size:.57rem;white-space:nowrap"><span class="mtf-sr" data-sr="'+e.label+'">'+e.label+'</span>'+((row.comps&&!virt)?' <button class="noprt" title="VQCC components" onclick="mtfCompToggle('+row.sr+')" style="background:none;border:1px solid #90caf9;color:#1565c0;border-radius:4px;font-size:.55rem;padding:0 .25rem;cursor:pointer">'+(MTF_OPEN[row.sr]?'\u25BE':'\u25B8')+'</button>':'')+'</td>';
    }
    if(row.isCustom){
      h+='<td style="font-size:.57rem"><input class="mtf-edit" type="text" value="'+(row.mat||'').replace(/"/g,'&quot;')+'" placeholder="Material" onchange="updateMTFMat('+row.sr+',this.value)"><span class="mtf-prt" style="display:none">'+(row.mat||'')+'</span></td>';
    }else if(virt){
      h+='<td style="font-size:.57rem;font-weight:700">'+row.mat+' '+_mcEsc(e.g.grade)+'</td>';
    }else{
      h+='<td style="font-size:.57rem">'+row.mat+((isConcRow&&eff.conc.cands.length)?'<div style="font-size:.5rem;color:#bf360c" class="noprt">Select grade (in the box above)</div>':'')+'</td>';
    }
    h+='<td style="font-size:.57rem"><textarea class="mtf-edit mtf-desc" rows="3" style="width:100%;font-size:.57rem;line-height:1.3;white-space:pre-line;resize:vertical;font-family:inherit;box-sizing:border-box" placeholder="Description of test" onchange="updateMTFDesc('+row.sr+',this.value)">'+_mtfEscHtml(row.desc||'')+'</textarea><span class="mtf-prt" style="display:none;white-space:pre-line">'+(row.desc||'')+'</span></td>';
    if(row.isCustom){
      h+='<td style="font-size:.57rem"><textarea class="mtf-edit" rows="2" style="width:100%;font-size:.57rem;line-height:1.3;resize:vertical;font-family:inherit;box-sizing:border-box" placeholder="Frequency" onchange="updateMTFFreq('+row.sr+',this.value)">'+_mtfEscHtml(row.freq||'')+'</textarea><span class="mtf-prt" style="display:none;white-space:pre-line">'+_mtfEscHtml(row.freq||'')+'</span></td>';
      h+='<td style="font-size:.57rem"><textarea class="mtf-edit" rows="2" style="width:100%;font-size:.57rem;line-height:1.3;resize:vertical;font-family:inherit;box-sizing:border-box" placeholder="Reference (IS / MoRTH ...)" onchange="updateMTFRef('+row.sr+',this.value)">'+_mtfEscHtml(row.ref||'')+'</textarea><span class="mtf-prt" style="display:none;white-space:pre-line">'+_mtfEscHtml(row.ref||'')+'</span></td>';
    }else{
    h+='<td style="font-size:.57rem">'+row.freq+'</td>';
    h+='<td style="font-size:.57rem">'+row.ref+'</td>';
    }
    if(virt){
      h+='<td class="r"><input class="mtf-edit" type="number" step="any" value="'+_mtfFmtQty(qty)+'" onchange="mtfConcQty(\''+e.g.grade+'\',this.value)"><span class="mtf-prt" style="display:none">'+_mtfFmtQty(qty)+'</span></td>';
      h+='<td class="r"><input class="mtf-edit" type="number" step="1" min="0" value="'+tests+'" onchange="mtfConcTests(\''+e.g.grade+'\',this.value)"><span class="mtf-prt" style="display:none">'+tests+'</span></td>';
    }else if(isConcRow){
      h+='<td class="r">'+_mtfFmtQty(qty)+'</td><td class="r">'+tests+'</td>';
    }else{
      h+='<td class="r"><input class="mtf-edit" type="number" step="any" value="'+_mtfFmtQty(qty)+'" onchange="updateMTFQty('+row.sr+',this.value)"><span class="mtf-prt" style="display:none">'+_mtfFmtQty(qty)+'</span></td>';
      h+='<td class="r"><input class="mtf-edit" type="number" step="1" min="0" value="'+tests+'" onchange="updateMTFTests('+row.sr+',this.value)"><span class="mtf-prt" style="display:none">'+tests+'</span></td>';
    }
    h+='<td class="r"><input class="mtf-edit" type="number" value="'+costPerTest+'" onchange="updateMTFCost('+row.sr+',this.value)"><span class="mtf-prt" style="display:none">'+costPerTest+'</span></td>';
    h+='<td class="r" style="font-weight:700;color:#d84315">'+totalCost.toFixed(2)+'</td>';
    h+='</tr>';
    if(virt)h+=mtfMixRowHtml(e.g.grade);
    else if(row.comps&&MTF_OPEN[row.sr])h+=mtfCompRowsHtml(row);
  });
  h+=mtfPickRowsHtml();
  tb.innerHTML=h;
  renderMTFPick();
  renderMTFConcBox(eff.conc);
  try{if(items&&items.length&&typeof rBOQ==='function')rBOQ();}catch(_e){} /* refresh [C] Testing in Abstract */
}

function getMaterialTotals(){
  /* Sum materials from Consumption Chart */
  var totals={cement:0,aggregate:0,sand:0,steel:0,bricks:0};
  
  /* Iterate through items and sum consumption factors */
  items.forEach(function(it){
    if(!it.cf)return;
    var _ecf=effCF(it);
    for(var mat in _ecf){
      var factor=_ecf[mat]||0;
      var lr=LR[mat];if(!lr)continue;
      var conv=lr.conv||1;
      var netQty=it.qty*factor*conv;
      
      /* Map to material categories */
      var lbl=(lr.label||'').toLowerCase();
      if(lbl.indexOf('cement')>=0)totals.cement+=netQty;
      else if(lbl.indexOf('aggregate')>=0||lbl.indexOf('metal')>=0||lbl.indexOf('grit')>=0)
        totals.aggregate+=netQty;
      else if(lbl.indexOf('sand')>=0)totals.sand+=netQty;
      else if(lbl.indexOf('steel')>=0||lbl.indexOf('tmt')>=0||mat==='ms_bars')
        totals.steel+=netQty;
      else if(lbl.indexOf('brick')>=0)totals.bricks+=netQty;
    }
  });
  
  return totals;
}

