/* Save / restore of the new state (travels inside the existing mtfConc payload) */
function mtfXForSave(){
  var cs={};
  mtfData.forEach(function(r){if(r.comps&&!r.isCustom)cs[r.sr]=r.comps.map(function(c){return {o:c.on?1:0,r:c.rate};});  /* objects, not [on,rate]: Firestore rejects arrays inside arrays */});
  return {comps:cs,mix:MTF_CONC_MIX,pick:MTF_PICK,dis:MTF_DIS};
}
function mtfXRestore(o){
  var x=(o&&o.x)||{};
  MTF_CONC_MIX=JSON.parse(JSON.stringify(x.mix||{}));
  MTF_PICK=JSON.parse(JSON.stringify(x.pick||[]));
  MTF_DIS=JSON.parse(JSON.stringify(x.dis||{}));
  MTF_OPEN={};
  mtfData.forEach(function(r){
    var base=MTF_COMPS[r.sr];if(!base||r.isCustom)return;
    r.comps=JSON.parse(JSON.stringify(base));
    var saved=(x.comps||{})[r.sr];
    if(saved)saved.forEach(function(s,i){if(r.comps[i]){var _on=Array.isArray(s)?s[0]:(s&&s.o),_rt=Array.isArray(s)?s[1]:(s&&s.r);r.comps[i].on=!!_on;r.comps[i].rate=+_rt||0;}});
    r._descAuto=mtfCompDesc(r);
  });
}

