      +'<button type="button" onclick="planXSecAddItem()" style="padding:.3rem .6rem;border:1px solid #1565c0;color:#1565c0;background:#fff;border-radius:4px;cursor:pointer;font-size:.72rem;font-weight:700">+ Layer</button>'
      +'<button type="button" onclick="planXSecRemoveLast()" style="padding:.3rem .6rem;border:1px solid #c62828;color:#c62828;background:#fff;border-radius:4px;cursor:pointer;font-size:.72rem">− Remove last</button>'
      +'</div>'
      +'<textarea id="xsLayers" rows="5" placeholder="Layer name | thickness  (one layer per line, top to bottom)" style="'+inp+'width:100%;box-sizing:border-box;font-family:monospace"></textarea>'
      +'<div style="margin:.4rem 0"><button type="button" id="xsAddBtn" onclick="planXSecAdd()" style="padding:.35rem .8rem;border:none;background:#1565c0;color:#fff;border-radius:6px;font-weight:700;cursor:pointer;font-size:.75rem">➕ Add to Plan</button></div>'
