    var i='padding:.2rem .3rem;border:1px solid #999;border-radius:4px;font-size:.72rem;', bt='padding:.2rem .5rem;border:1px solid #1a237e;color:#1a237e;background:#fff;border-radius:4px;cursor:pointer;font-weight:700;';
    d.innerHTML='<b id="peSel" style="width:100%;color:#1a237e">✏️ Edit</b>'
