     +'<button type="button" style="'+bt+'" onclick="planEditAllColor()" title="Apply this colour to all lines / text">Apply colour to all</button>'
     +'<span style="display:inline-flex;align-items:center;gap:.2rem">Line thickness <button type="button" style="'+bt+'" onclick="planEditStep(\'peW\',-0.5)">−</button><input id="peW" type="number" step="0.5" min="0.5" style="'+i+'width:3.2rem" onchange="planEditApply(\'w\')"><button type="button" style="'+bt+'" onclick="planEditStep(\'peW\',0.5)">+</button></span>'
     +'<span style="display:inline-flex;align-items:center;gap:.2rem"><span id="peFsLbl">Text size</span> <button type="button" style="'+bt+'" onclick="planEditStep(\'peFs\',-0.5)">−</button><input id="peFs" type="number" step="0.5" min="0.5" style="'+i+'width:3.2rem" onchange="planEditApply(\'fs\')"><button type="button" style="'+bt+'" onclick="planEditStep(\'peFs\',0.5)">+</button></span>'
     +'<label>Name <input id="peName" type="text" style="'+i+'width:9rem" onchange="planEditApply(\'name\')"></label>'
     +'<label id="peLenWrap" style="display:none;align-items:center;gap:.2rem">Length (px) <input id="peLen" type="number" step="5" min="5" style="'+i+'width:4rem" onchange="planEditApply(\'len\')"></label>'
     +'<span id="peXWrap" style="display:none;align-items:center;gap:.4rem"><label>Label line length <input id="peLead" type="number" step="5" min="0" style="'+i+'width:3.5rem" onchange="planEditApply(\'lead\')"></label><label>Section width <input id="peSw" type="number" step="10" min="80" style="'+i+'width:3.8rem" onchange="planEditApply(\'sw\')"></label></span>'
     +'<button type="button" id="peExplode" style="display:none;'+bt+'border-color:#c62828;color:#c62828" onclick="planXSecExplode()" title="Split the cross-section into separate lines, boxes and texts for individual editing">🧩 Split into editable parts</button>'
