  /* Cross-section → individual shapes (every line / box / text separately editable) */
  window.planXSecExplode=function(){
    var i=PLAN.selectedIdx, s=PLAN.shapes[i]; if(!s||s.type!=='xsec'){showToast('Select a cross-section first','error');return;}
    if(!confirm('This cross-section will be split into individual lines / boxes / texts so each can be edited separately. (Undo works.) Continue?'))return;
    saveHistory();
    var out=[], LC=s.lc||PLAN.lineColor, LW=parseFloat(s.lw)||1, FS=parseFloat(s.fs)||1, LEAD=(s.lead!=null?parseFloat(s.lead):14), XW=parseFloat(s.sw)||XS_W;
    var sp=xsSplit(s), stack=sp.stack, exc=sp.exc, n=stack.length, x=s.x, y=s.y;
    var wC=parseFloat(s.width)||0, wB=parseFloat(s.berm)||0, tot=(wC+2*wB)||1;
    var pxB=Math.round(XW*wB/tot), pxC=XW-2*pxB, top=y+36, H=0; stack.forEach(function(l){H+=xsLayerH(l);}); if(!n)H=24;
    var m=document.createElement('canvas').getContext('2d');
    function T(txt,tx,ty,fsz,al){ txt=String(txt||''); if(!txt)return; m.font='bold '+fsz+'px sans-serif'; var w=m.measureText(txt).width; var lx=al==='c'?tx-w/2:(al==='r'?tx-w:tx); out.push({type:'text',x:Math.round(lx),y:Math.round(ty-fsz/2),label:txt,color:LC,fs:fsz}); }
    function Ln(a,b,c,d,st){ out.push({type:'line',x1:Math.round(a),y1:Math.round(b),x2:Math.round(c),y2:Math.round(d),style:st||'solid',width:LW,color:LC}); }
    var ttl=s.title||'Cross Section'; T(ttl,x+XW/2,y+4,10*FS,'c'); m.font='bold '+(10*FS)+'px sans-serif'; var tw=m.measureText(ttl).width; Ln(x+XW/2-tw/2,y+10,x+XW/2+tw/2,y+10);
    var dy=top-8; Ln(x+pxB,dy,x+pxB+pxC,dy); Ln(x+pxB,dy-3,x+pxB,dy+3); Ln(x+pxB+pxC,dy-3,x+pxB+pxC,dy+3); T((s.width||'')+' m',x+pxB+pxC/2,dy-6,8*FS,'c');
    if(wB>0){ Ln(x,dy,x+pxB,dy); Ln(x+pxB+pxC,dy,x+XW,dy); T(s.berm+' m',x+pxB/2,dy-6,8*FS,'c'); T(s.berm+' m',x+XW-pxB/2,dy-6,8*FS,'c'); }
    var exH=exc?20:0;
    if(exc){ var ex0=x+pxB-6, exW=pxC+12;
      Ln(ex0,top,ex0+exW,top,'dashed'); Ln(ex0+exW,top,ex0+exW,top+H+exH,'dashed'); Ln(ex0+exW,top+H+exH,ex0,top+H+exH,'dashed'); Ln(ex0,top+H+exH,ex0,top,'dashed');
      Ln(x-30,top,ex0,top); Ln(ex0+exW,top,x+XW+30,top);
      for(var gi=x-30;gi<ex0-4;gi+=7)Ln(gi,top,gi-4,top+5); for(var gk=ex0+exW+4;gk<x+XW+30;gk+=7)Ln(gk,top,gk-4,top+5);
    }
    var cy=top, ys=[];
    for(var a=0;a<n;a++){ var lh=xsLayerH(stack[a]); out.push({type:'rect',x:x+pxB,y:cy,w:pxC,h:lh,kind:xsKind(stack[a].n),color:LC,width:LW,label:stack[a].n}); ys.push({y:cy,h:lh}); cy+=lh; }
    if(wB>0){ out.push({type:'rect',x:x,y:top,w:pxB,h:H,kind:'mur',color:LC,width:LW,label:'Berm L'}); out.push({type:'rect',x:x+XW-pxB,y:top,w:pxB,h:H,kind:'mur',color:LC,width:LW,label:'Berm R'}); T('Hard Murum',x-3,top+H/2,7*FS,'r'); }
    var rx=x+XW+LEAD, lastTy=top-6;
    for(var j=0;j<n;j++){ var my=ys[j].y+ys[j].h/2, ty=Math.max(my,lastTy+11); lastTy=ty; Ln(x+pxB+pxC*0.65,my,rx-2,ty); T((stack[j].n||'')+(stack[j].t?'  ('+stack[j].t+')':''),rx,ty,8*FS,'l'); }
    if(exc) T('Excavation'+(exc.t?' ('+exc.t+')':''),x+pxB+pxC/2,top+H+exH/2,8*FS,'c');
    PLAN.shapes.splice(i,1); PLAN.selectedIdx=null; out.forEach(function(q){PLAN.shapes.push(q);});
    XS_EDIT=null; xsList(); drawAll();
    showToast('Every line / box / text can now be selected and edited separately','success');
  };

  /* init on DOMContentLoaded */
