/* ── Measurement Sheet print prep ──────────────────────────────────────
   Column widths (Floor narrow, Detail wide) + bigger values in Floor / Detail /
   No. / Length / Width / Height. Detail text keeps full size when it fits on
   one line, otherwise shrinks just enough to fit. Applied only while printing. */
(function(){
  var W=[3.5,7,7,36,4.5,8,8,8,10,8,0];   /* Sr, Item, Floor, Detail, No, L, W, H, Qty, Unit, Act */
  var cv=null;
  function textW(txt,px){
    if(!cv)cv=document.createElement('canvas').getContext('2d');
    cv.font='400 '+px+'px Arial, Helvetica, sans-serif';
    return cv.measureText(txt).width;
  }
  function imp(el,prop,val){el.style.setProperty(prop,val,'important');}
  window.addEventListener('beforeprint',function(){
    var p5=document.getElementById('p5');if(!p5)return;
    var tbl=p5.querySelector('table');if(!tbl)return;
    imp(tbl,'table-layout','fixed');
    var ths=tbl.querySelectorAll('thead th');
    for(var k=0;k<ths.length&&k<W.length;k++){if(W[k])imp(ths[k],'width',W[k]+'%');imp(ths[k],'font-size','8.5pt');imp(ths[k],'white-space','normal');imp(ths[k],'padding','.18rem .12rem');imp(ths[k],'line-height','1.15');}
    var BASE=9.5, MIN=6.5;
    var availPx=(210-12-10)*96/25.4*(W[3]/100)-8.3-6.4-4;   /* Detail column − paddings */
    p5.querySelectorAll('td input').forEach(function(inp){
      var pt=BASE;
      if(inp.classList.contains('ms-det')){
        var w=textW(inp.value||'',BASE*96/72);
        if(w>availPx)pt=Math.max(MIN,Math.floor(BASE*availPx/w*4)/4);
        imp(inp,'white-space','nowrap');
      }
      imp(inp,'font-size',pt+'pt');
    });
  });
  window.addEventListener('afterprint',function(){
    var p5=document.getElementById('p5');if(!p5)return;
    var tbl=p5.querySelector('table');if(!tbl)return;
    tbl.style.removeProperty('table-layout');
    tbl.querySelectorAll('thead th').forEach(function(th){th.style.removeProperty('width');th.style.removeProperty('font-size');th.style.removeProperty('white-space');th.style.removeProperty('padding');th.style.removeProperty('line-height');});
    p5.querySelectorAll('td input').forEach(function(inp){inp.style.removeProperty('font-size');inp.style.removeProperty('white-space');});
  });
})();

/* ══════════════════════════════════════════════════════════════════════
   TEST REPORT  (Lab testing letter + Mahitipatrak)  — Tab 19
   - Auto-generate from the estimate  OR  blank (without estimate)
   - All fields editable, test rows can be added / deleted / duplicated
   - Officer / office names are not hard-coded — the user fills them in once and they are saved
   - Individual print (no effect on Print All — it works as before)
   ══════════════════════════════════════════════════════════════════════ */
var TR=null;
var TR_DRAFT_KEY='atpTestReportDraft';
var TR_OFFICE_KEY='atpTestReportOffice';
var TR_GRADES=['M-5','M-7.5','M-10','M-15','M-20','M-25','M-30','M-35','M-40'];
var TR_WORDS=['Zero','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen'];
/* office-level fields: fill once, they auto-fill in all later reports */
var TR_OFFICE_FIELDS=['jaKra','toLine1','toLine2','subject','subPlace','divPlace','boardPlace','vqcLine','repName','repDesig','priorTests','purpose','status'];
var TR_PRESETS={
  coarse:{name:'Basic Test of Coarse Aggregate (10/20MM Metal)',test:'Sieve Analysis'},
  fine:{name:'Basic Test of Fine Aggregate',test:'Fineness Modulus'},
  brick:{name:'Brick',test:'Water Absorption'},
  cement:{name:'Cement',test:'Compressive Strength'},
  steel:{name:'TMT Steel Bar',test:'Tensile Strength, Yield Stress, Elongation'},
  ftile:{name:'Flooring Tiles',test:'Transverse Strength, Water Absorption'},
  mtile:{name:'Mangalore Tiles',test:'Breaking Load, Water Absorption'},
  paver:{name:'Paver Blocks',test:'Compressive Strength, Water Absorption'},
  custom:{name:'',test:''}
};
/* Testing tab (mtfData) sr  ->  report row preset */
var TR_MTF_MAP={1:'cement',2:'coarse',3:'fine',5:'steel',6:'brick',7:'ftile',8:'mtile',9:'paver'};

function trWord(n){n=parseInt(n)||0;return TR_WORDS[n]!==undefined?TR_WORDS[n]:String(n);}
function trEsc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function trUid(){return 'tr'+Date.now().toString(36)+Math.floor(Math.random()*46656).toString(36);}
function trIsoToDmy(s){var m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(s||'');return m?(m[3]+'-'+m[2]+'-'+m[1]):(s||'');}

function trOfficeGet(){try{return JSON.parse(localStorage.getItem(TR_OFFICE_KEY)||'{}')||{};}catch(e){return {};}}
function trOfficeSave(){
  if(!TR)return;var o={};
  TR_OFFICE_FIELDS.forEach(function(k){o[k]=TR.meta[k]||'';});
  try{localStorage.setItem(TR_OFFICE_KEY,JSON.stringify(o));}catch(e){}
}
function trDefaultMeta(){
  var o=trOfficeGet();
  var def={
    jaKra:'',toLine1:'सहाय्यक संशोधन अधिकारी,',toLine2:'क्षेत्रीय प्रयोगशाळा बीड/छत्रपती संभाजीनगर',
    subject:'बांधकाम साहित्याच्या चाचण्या बाबत.',
    subPlace:'',divPlace:'',boardPlace:'बीड / छत्रपती संभाजीनगर',
    vqcLine:'कार्यकारी अभियंता दक्षता व गुण नियंत्रण मंडळ, औरंगाबाद',
    repName:'',repDesig:'',
    priorTests:'मंजुर अंदाजपत्रकामधील Item च्या परिमाणानुसार.',
    purpose:'बांधकाम साहित्याची गुणवत्ता तपासणीसाठी.',status:'प्रगतीत'
  };
  var m={};
  TR_OFFICE_FIELDS.forEach(function(k){m[k]=(o[k]!==undefined&&o[k]!=='')?o[k]:def[k];});
  /* per-report fields */
  m.date='';m.workName='';m.estCost='';m.feeAmt='';m.bankName='';m.ddNo='';m.tenderNo='';m.tenderDate='';
  return m;
}
function trNewRow(kind,preset){
  var p=TR_PRESETS[preset||'custom']||TR_PRESETS.custom;
  return {id:trUid(),kind:kind||'other',name:p.name,grade:'M-20',date:'',test:(kind==='cube'?'Compressive Strength':p.test),
    n:1,qtyTxt:'One Test',smpTxt:'One Set',qAuto:true};
}
function trApplyAuto(r){if(r.qAuto){r.qtyTxt=trWord(r.n)+' Test';r.smpTxt=trWord(r.n)+' Set';}}
function trRowName(r){return r.kind==='cube'?((r.grade||'M-__')+' Cement Concrete Cube'):(r.name||'');}

/* MORTH Table-1700-9 : cube sets for given concrete qty (cum). the qty is rounded to pick the band */
function trCubeSets(qty){
  var q=Math.round(qty||0);
  if(q<=0)return 0;
  if(q<=5)return 1;
  if(q<=15)return 2;
  if(q<=30)return 3;
  if(q<=50)return 4;
  return 4+Math.ceil((q-50)/50);
}
function trGradeOf(desc){
  var m=/(?:^|[^A-Za-z])M[\s\-]?(5|7\.5|10|15|20|25|30|35|40|45|50)(?![0-9])/.exec(desc||'');
  return m?('M-'+m[1]):null;
}
function trMtfTests(row,mats){
  var qty=0,f=row.qtyFormula||'';
  if(row._qty!==undefined&&row._qty!==null)qty=row._qty;
  else if(f==='cement')qty=mats.cement||0;
  else if(f==='aggregate')qty=mats.aggregate||0;
  else if(f==='sand')qty=mats.sand||0;
  else if(f==='steel/1000')qty=(mats.steel||0)/1000;
  else if(f==='bricks*1000')qty=(mats.bricks||0)*1000;
  qty=qty||0;
  if(row._tests!==undefined&&row._tests!==null)return row._tests;
  return (row.threshold>0&&qty>0)?Math.ceil(qty/row.threshold):((qty>0&&row.threshold===0)?1:0);
}

/* ── Build the rows from the estimate ── */
function trRowsFromEstimate(){
  var rows=[],mats={cement:0,aggregate:0,sand:0,steel:0,bricks:0},note='';
  try{mats=getMaterialTotals();}catch(e){}
  /* 1) Testing tab (material tests) — rows whose tests>0 */
  try{
    if(typeof mtfData!=='undefined'){
      mtfData.forEach(function(mr){
        if(mr.sr===4)return; /* Cement Concrete -> cubes below */
        var t=trMtfTests(mr,mats);
        if(!(t>0))return;
        var pk=mr.isCustom?'custom':TR_MTF_MAP[mr.sr];
        if(!pk)return;
        var r=trNewRow('other',pk);
        if(mr.isCustom){r.name=mr.mat||'';r.test=String(mr.desc||'').split('\n')[0]||'';}
        r.n=t;r.qAuto=true;trApplyAuto(r);rows.push(r);
      });
    }
  }catch(e){}
  /* 2) Concrete cubes — as per the grade-wise rows in the Testing tab (same numbers) */
  var conc=mtfConcEff();
  conc.grades.forEach(function(g){
    if(!(g.tests>0))return;
    var r=trNewRow('cube');r.grade=g.grade;r.n=g.tests;r.qAuto=true;trApplyAuto(r);rows.push(r);
  });
  if(conc.grades.length&&MTF_CONC_OK!==conc.sig)note='The grade-wise concrete items have not been confirmed yet in the Testing tab. Press "Looks correct" there, then generate again.';
  return {rows:rows,note:note};

}
function trEstCostText(){
  try{
    if(!items||!items.length)return '';
    var g=calcGrand();if(!(g>0))return '';
    return (g/100000).toFixed(2)+' लक्ष';
  }catch(e){return '';}
}
function trGenerate(fromBtn){
  if(fromBtn&&TR&&TR.rows&&TR.rows.length&&!confirm('The test rows in your current report will be replaced. Generate a new one from the estimate?'))return;
  var g=trRowsFromEstimate();
  var prev=TR&&TR.meta?TR.meta:null;
  TR={mode:'estimate',forWork:((R('pName')||{}).value||''),meta:trDefaultMeta(),rows:g.rows,note:g.note};
  if(prev){['date','feeAmt','bankName','ddNo','tenderNo','tenderDate'].forEach(function(k){TR.meta[k]=prev[k]||'';});}
  TR.meta.workName=((R('pName')||{}).value||'').trim();
  TR.meta.estCost=trEstCostText();
  trSaveDraft();trRender();
  if(fromBtn&&typeof showToast==='function')showToast(g.rows.length?('✅ '+g.rows.length+' test rows generated from the estimate'):'No testable items found in the estimate \u2014 use + Add','info');
}
function trBlank(fromBtn){
  if(fromBtn&&TR&&TR.rows&&TR.rows.length&&!confirm('The current report will be cleared. Create a blank report (without estimate)?'))return;
  TR={mode:'blank',forWork:'',meta:trDefaultMeta(),rows:[],note:''};
  trSaveDraft();trRender();
}

/* ── Save / load ── */
function trSaveDraft(){try{if(TR)localStorage.setItem(TR_DRAFT_KEY,JSON.stringify(TR));}catch(e){}}
function trLoadDraft(){try{var s=localStorage.getItem(TR_DRAFT_KEY);if(s){var o=JSON.parse(s);if(o&&o.meta&&Array.isArray(o.rows))return o;}}catch(e){}return null;}
function trForSave(){return TR?JSON.parse(JSON.stringify(TR)):null;}
function trRestore(obj){
  if(obj&&obj.meta&&Array.isArray(obj.rows)){TR=JSON.parse(JSON.stringify(obj));trSaveDraft();}
  else{TR=null;try{localStorage.removeItem(TR_DRAFT_KEY);}catch(e){}}  /* no report for this estimate yet — a new one is generated when the tab is opened */
  var p=R('p19');if(p&&p.classList.contains('on'))trInit();
}

/* ── Tab open ── */
function trInit(){
  if(!TR){var d=trLoadDraft();if(d)TR=d;}
  var cur=((R('pName')||{}).value||'');
  if(!TR){
    if(items&&items.length)trGenerate(false);else trBlank(false);
    return;
  }
  trRender();
}

/* ── Edit handlers ── */
function trMeta(k,v){
  if(!TR)return;TR.meta[k]=v;
  if(TR_OFFICE_FIELDS.indexOf(k)>=0)trOfficeSave();
  trSaveDraft();trPreviewSoon();
}
function trRowSet(id,k,v){
  var r=TR.rows.find(function(x){return x.id===id;});if(!r)return;
  if(k==='n'){r.n=Math.max(0,parseInt(v)||0);trApplyAuto(r);}
  else if(k==='qtyTxt'||k==='smpTxt'){r[k]=v;r.qAuto=false;}
  else r[k]=v;
  trSaveDraft();
  if(k==='n'||k==='grade'||k==='kind'){trRenderRows();}
  trPreviewSoon();
}
function trAddRow(kind,preset){
  if(!TR)trBlank(false);
  var r=trNewRow(kind,preset);TR.rows.push(r);trSaveDraft();trRenderRows();trPreviewSoon();
}
function trAddFromSelect(){
  var s=R('trAddSel');if(!s||!s.value)return;
  if(s.value==='cube')trAddRow('cube');else trAddRow('other',s.value);
  s.value='';
}
function trDelRow(id){
  TR.rows=TR.rows.filter(function(x){return x.id!==id;});
  trSaveDraft();trRenderRows();trPreviewSoon();
}
function trDupRow(id){
  var i=TR.rows.findIndex(function(x){return x.id===id;});if(i<0)return;
  var c=JSON.parse(JSON.stringify(TR.rows[i]));c.id=trUid();c.date='';
  TR.rows.splice(i+1,0,c);trSaveDraft();trRenderRows();trPreviewSoon();
}
function trMoveRow(id,dir){
  var i=TR.rows.findIndex(function(x){return x.id===id;});var j=i+dir;
  if(i<0||j<0||j>=TR.rows.length)return;
  var t=TR.rows[i];TR.rows[i]=TR.rows[j];TR.rows[j]=t;
  trSaveDraft();trRenderRows();trPreviewSoon();
}
function trRefreshFromEstimate(){
  if(!TR)return;
  TR.meta.workName=((R('pName')||{}).value||'').trim();
  TR.meta.estCost=trEstCostText();
  TR.forWork=TR.meta.workName;
  trSaveDraft();trRender();
}

/* ── UI render ── */
function trField(label,key,opts){
  opts=opts||{};
  var v=TR.meta[key]||'';
  var inp=opts.area
    ?'<textarea rows="2" class="tr-in" oninput="trMeta(\''+key+'\',this.value)">'+trEsc(v)+'</textarea>'
    :'<input class="tr-in" type="'+(opts.type||'text')+'" value="'+trEsc(v)+'" placeholder="'+trEsc(opts.ph||'')+'" oninput="trMeta(\''+key+'\',this.value)">';
  return '<label class="tr-f'+(opts.wide?' tr-wide':'')+'"><span>'+label+(opts.office?' <em title="Fill once \u2014 it will auto-fill in future reports">●</em>':'')+'</span>'+inp+'</label>';
}
function trRender(){
  var box=R('trBox');if(!box)return;
  if(!TR){box.innerHTML='';return;}
  var curWork=((R('pName')||{}).value||'').trim();
  var warn='';
  if(TR.mode==='estimate'&&curWork&&TR.forWork!==curWork){
    warn='<div class="tr-warn noprt">⚠️ This report was made for <b>'+trEsc(TR.forWork||'(another estimate)')+'</b>. Current estimate: <b>'+trEsc(curWork)+'</b>. '
      +'<button class="tr-btn" onclick="trGenerate(true)">🔄 Generate from current estimate</button></div>';
  }
  var h=warn;
  if(TR.note)h+='<div class="tr-note noprt">ℹ️ '+trEsc(TR.note)+'</div>';
  h+='<div class="tr-sec"><div class="tr-h">📋 Work &amp; letter details</div><div class="tr-grid">'
    +trField('Name of Work (कामाचे नांव)','workName',{wide:true,area:true})
    +trField('अंदाजपत्रकातील एकूण किंमत','estCost',{ph:'15.00 लक्ष'})
    +trField('दिनांक (दि:-)','date',{type:'date'})
    +trField('निविदा क्रमांक','tenderNo',{ph:'जा.क्र/लेखा/निविदा/ब-१ क्र. ___'})
    +trField('निविदा दिनांक','tenderDate',{ph:'DD-MM-YYYY'})
    +trField('चाचणी शुल्क रुपये','feeAmt')
    +trField('स्टेट बँक ऑफ (शाखा)','bankName')
    +trField('DD / धनादेश क्रमांक','ddNo')
    +'</div></div>';
  h+='<div class="tr-sec"><div class="tr-h">🏢 Office / Officer details <span class="tr-sub">● fill once, it will auto-fill in future reports. Officer names are not taken from here \u2014 please enter them yourself.</span></div><div class="tr-grid">'
    +trField('जा.क्र.','jaKra',{office:1,ph:'कॅम्प/बीड-__'})
    +trField('उपविभाग ठिकाण (सा.बां. उपविभाग, ___)','subPlace',{office:1,ph:'उदा. परळी वै.'})
    +trField('विभाग ठिकाण (सा.बां. विभाग, ___)','divPlace',{office:1,ph:'उदा. अंबाजोगाई'})
    +trField('प्रति — ओळ 1 (पदनाम)','toLine1',{office:1})
    +trField('प्रति — ओळ 2 (प्रयोगशाळा)','toLine2',{office:1})
    +trField('विषय','subject',{office:1,wide:true})
    +trField('नमुने घेऊन जाणारे कर्मचारी — नाव','repName',{office:1,ph:'श्री. ____'})
    +trField('कर्मचारी — हुद्दा','repDesig',{office:1,ph:'उदा. स्था.अ.स.'})
    +trField('शुल्क DD कोणाच्या नावे','vqcLine',{office:1,wide:true})
    +trField('माहितीपत्रक — मंडळ ठिकाण','boardPlace',{office:1})
    +trField('पूर्वी घेतलेल्या चाचण्या','priorTests',{office:1,wide:true})
    +trField('चाचणीचा उद्देश','purpose',{office:1,wide:true})
    +trField('कामाची सद्यस्थिती','status',{office:1})
    +'</div></div>';
  h+='<div class="tr-sec"><div class="tr-h">🧪 Tests (माहितीपत्रकातील तक्ता)</div><div id="trRows"></div>'
    +'<div class="tr-addbar noprt"><select id="trAddSel" class="tr-in" style="max-width:260px" onchange="trAddFromSelect()">'
    +'<option value="">➕ Add test…</option><option value="cube">Concrete Cube (M-grade)</option>'
    +'<option value="coarse">Coarse Aggregate</option><option value="fine">Fine Aggregate</option><option value="brick">Brick</option>'
    +'<option value="cement">Cement</option><option value="steel">Steel</option><option value="ftile">Flooring Tiles</option>'
    +'<option value="mtile">Mangalore Tiles</option><option value="paver">Paver Blocks</option><option value="custom">Other / Custom</option></select></div></div>';
  h+='<div class="tr-sec"><div class="tr-h">👁 Preview <span class="tr-sub">(check before printing)</span></div><iframe id="trPrev" class="tr-prev" title="Test report preview"></iframe></div>';
  box.innerHTML=h;
  trRenderRows();trPreview();
}
function trRenderRows(){
  var c=R('trRows');if(!c||!TR)return;
  if(!TR.rows.length){c.innerHTML='<div class="tr-empty">No tests yet. Use "➕ Add test" below (or 🔄 Generate from Estimate).</div>';return;}
  var h='<datalist id="trGradeList">'+TR_GRADES.map(function(g){return '<option value="'+g+'">';}).join('')+'</datalist>';
  h+='<div class="tr-trow tr-thead"><div>#</div><div>Material / Grade</div><div>Date (नमुना)</div><div>Test name</div><div>No.</div><div>परिमाण (Test)</div><div>नमुना (Set)</div><div></div></div>';
  TR.rows.forEach(function(r,i){
    var id=r.id;
    var nameCell=(r.kind==='cube')
      ?'<div class="tr-cubewrap"><input class="tr-in" list="trGradeList" value="'+trEsc(r.grade)+'" oninput="trRowSet(\''+id+'\',\'grade\',this.value)" style="width:70px" title="Grade (M-10, M-20 …)"><span class="tr-cubetxt">Cement Concrete Cube</span></div>'
      :'<input class="tr-in" value="'+trEsc(r.name)+'" placeholder="Material" oninput="trRowSet(\''+id+'\',\'name\',this.value)">';
    h+='<div class="tr-trow"><div class="tr-no">'+(i+1)+'</div>'
      +'<div>'+nameCell+'</div>'
      +'<div><input class="tr-in" type="date" value="'+trEsc(r.date)+'" onchange="trRowSet(\''+id+'\',\'date\',this.value)"></div>'
      +'<div><input class="tr-in" value="'+trEsc(r.test)+'" oninput="trRowSet(\''+id+'\',\'test\',this.value)"></div>'
      +'<div><input class="tr-in" type="number" min="0" step="1" value="'+r.n+'" onchange="trRowSet(\''+id+'\',\'n\',this.value)" style="width:56px"></div>'
      +'<div><input class="tr-in" value="'+trEsc(r.qtyTxt)+'" oninput="trRowSet(\''+id+'\',\'qtyTxt\',this.value)"></div>'
      +'<div><input class="tr-in" value="'+trEsc(r.smpTxt)+'" oninput="trRowSet(\''+id+'\',\'smpTxt\',this.value)"></div>'
      +'<div class="tr-acts noprt"><button class="tr-ic" title="Up" onclick="trMoveRow(\''+id+'\',-1)">↑</button><button class="tr-ic" title="Down" onclick="trMoveRow(\''+id+'\',1)">↓</button>'
      +'<button class="tr-ic" title="Duplicate (for a different date)" onclick="trDupRow(\''+id+'\')">⧉</button>'
      +'<button class="tr-ic tr-del" title="Delete" onclick="trDelRow(\''+id+'\')">🗑</button></div></div>';
  });
  c.innerHTML=h;
}

/* ── Print document builder ── */
