function trPrint(which){
  if(!TR){return;}
  if(which!=='letter'&&!TR.rows.length&&!confirm('The test table is empty. Print anyway?'))return;
  trSaveDraft();
  var html=trBuildHTML(which||'both');
  var f=document.createElement('iframe');
  f.setAttribute('aria-hidden','true');
  f.style.cssText='position:fixed;left:-9999px;top:0;width:210mm;height:297mm;border:0;visibility:hidden';
  document.body.appendChild(f);
  var d=f.contentWindow.document;d.open();d.write(html);d.close();
  var done=false;
  function go(){
    if(done)return;done=true;
    try{f.contentWindow.focus();f.contentWindow.print();}catch(e){}
    setTimeout(function(){try{f.remove();}catch(e){}},60000);
  }
  if(f.contentWindow.document.fonts&&f.contentWindow.document.fonts.ready){f.contentWindow.document.fonts.ready.then(function(){setTimeout(go,150);});setTimeout(go,1200);}
  else setTimeout(go,500);
}

