/* ══ PASTE FROM EXCEL — Measurement Sheet ══════════════════════════════════
   When Excel cells are pasted into any cell of the Measurement Sheet (Detail / Nos / L / B / D),
   they fill from that cell to the right (columns) and downwards (rows) — just like Excel.
   If there are not enough rows, new rows are added to that item (floor = that of the last row).
   A constant-only formula from Excel (=2*3.5+1.2, SUM/AVERAGE of numbers) is stored as a formula
   (r._f). For a cell-reference formula (=B2*3, =SUM(A1:A5)) the value calculated by Excel is taken.
   Pasting a single cell is a normal paste. Linked fields (🔗) are skipped. */
var ATP_XL_COLS=['lbl','n','l','b','d'];
function atpXlNum(s){
  if(s===null||s===undefined)return null;
  s=String(s).replace(/[,\s\u00a0]/g,'');
  if(s==='')return null;
  var v=parseFloat(s);
  return isNaN(v)?null:v;
}
/* Excel formula -> app formula ('=...') if all operands are numbers, otherwise null */
function atpXlFormula(f){
  if(!f)return null;
  var e=String(f).trim();
  if(e.charAt(0)!=='=')return null;
  e=e.substring(1).replace(/\s+/g,'');
  var g=0;
  while(/(SUM|AVERAGE)\(([^()]*)\)/i.test(e)&&g++<10){
    e=e.replace(/(SUM|AVERAGE)\(([^()]*)\)/ig,function(m,fn,args){
      var p=args.split(/[,;]/),k;
      for(k=0;k<p.length;k++)if(!/^[0-9]*\.?[0-9]+$/.test(p[k]))return 'X';
      var s='('+p.join('+')+')';
      return /^AVERAGE$/i.test(fn)?'('+s+'/'+p.length+')':s;
    });
  }
  if(!e||!/^[0-9+\-*\/().]+$/.test(e)||e.indexOf('//')>-1||e.indexOf('**')>-1)return null;
  try{var r=Function('"use strict";return ('+e+')')();if(typeof r!=='number'||!isFinite(r))return null;}catch(x){return null;}
  return '='+e;
}
/* Clipboard -> grid of {v:displayText, f:excelFormula}. the Excel HTML clipboard has an x:fmla attribute */
function atpXlGrid(cd){
  var html=cd.getData('text/html')||'',text=cd.getData('text/plain')||'';
  var tl=text.replace(/\r/g,'').replace(/\n+$/,'').split('\n').map(function(l){return l.split('\t');});
  var grid=[];
  if(html&&/<td/i.test(html)&&typeof DOMParser!=='undefined'){
    try{
      var doc=new DOMParser().parseFromString(html,'text/html');
      Array.prototype.forEach.call(doc.querySelectorAll('tr'),function(tr){
        var row=[];
        Array.prototype.forEach.call(tr.querySelectorAll('td,th'),function(td){
          row.push({v:(td.textContent||'').replace(/\s+/g,' ').trim(),f:td.getAttribute('x:fmla')||''});
        });
        grid.push(row);
      });
    }catch(err){grid=[];}
  }
  /* if the html grid does not match the plain text, use the plain text (values only) */
  if(!grid.length||grid.length!==tl.length||grid[0].length!==tl[0].length){
    grid=tl.map(function(r){return r.map(function(c){return {v:c.trim(),f:''};});});
  }
  return grid;
}
function atpXlPaste(iIdx,rIdx,col0,grid){
  var it=items[iIdx];if(!it||!it.rows)return;
  var targets=[],k;
  for(k=rIdx;k<it.rows.length;k++){var rr=it.rows[k];if(rr&&!rr.isTot&&!rr.isPct)targets.push(rr);}
  var added=0,skipped=0,valOnly=0,cells=0,gi,ci;
  for(gi=0;gi<grid.length;gi++){
    var line=grid[gi],r=targets[gi];
    if(!r){
      r={lbl:'',n:1,l:0,b:0,d:0,qty:0,fl:msrLastFloor(it)};
      var ti=it.rows.findIndex(function(x){return x.isTot;});
      if(ti>=0)it.rows.splice(ti,0,r);else it.rows.push(r);
      targets.push(r);added++;
    }
    var lf=r._linkedFrom?msrLinkFieldsOf(r):[];
    for(ci=0;ci<line.length;ci++){
      var f=ATP_XL_COLS[col0+ci];if(!f)break;
      var c=line[ci];
      if(lf.indexOf('qty')>-1||(f!=='lbl'&&lf.indexOf(f)>-1)){skipped++;continue;}
      cells++;
      if(f==='lbl'){r.lbl=c.v;continue;}
      var fx=atpXlFormula(c.f),val=null;
      if(fx){val=msrResolve(fx,iIdx);if(val===null)fx=null;}
      if(!fx){val=atpXlNum(c.v);if(c.f)valOnly++;}
      if(f==='n'){r.n=val||1;continue;}
      if(!r._f)r._f={};
      if(fx){r._f[f]=fx;r[f]=val;}else{delete r._f[f];r[f]=val;}
    }
  }
  msrSyncAllRows();
  for(var a=0;a<items.length;a++)items[a]=recalcItem(items[a]);
  rMS();updateAll();
  if(typeof showToast==='function'){
    var msg='Excel paste: '+grid.length+' row(s)'+(added?' ('+added+' new)':'');
    if(valOnly)msg+=' — '+valOnly+' cell(s) had a cell-reference formula, value was taken';
    if(skipped)msg+=' — '+skipped+' linked cell(s) skip';
    showToast(msg,valOnly||skipped?'info':'success');
  }
}
document.addEventListener('paste',function(e){
  var t=e.target;
  if(!t||t.tagName!=='INPUT')return;
  var tr=t.closest?t.closest('tr[id^="msr_"]'):null;if(!tr)return;
  var m=/^msr_(\d+)_(\d+)$/.exec(tr.id);if(!m)return;
  var fm=/msrUpd\(\d+,\d+,this,'(\w+)'\)/.exec(t.getAttribute('oninput')||'');if(!fm)return;
  var col=ATP_XL_COLS.indexOf(fm[1]);if(col<0)return;
  var cd=e.clipboardData;if(!cd)return;
  var text=cd.getData('text/plain')||'';
  if(text.indexOf('\t')<0&&text.replace(/\r?\n$/,'').indexOf('\n')<0)return; /* single cell = normal paste */
  e.preventDefault();
  atpXlPaste(parseInt(m[1],10),parseInt(m[2],10),col,atpXlGrid(cd));
},true);

/* ══ MEASUREMENT SHEET — EXCEL DOWNLOAD / UPLOAD ═══════════════════════════
   Template: a blank Excel with only headings. Fill Item No + Nos/L/B/D and upload — the app takes Description/rate from SSR.
   A cell-reference formula in Nos/L/B/D -> live link in the app (=1.0L*2). The rules are on the right side of the table (column N).
   Download: the measurement rows of every item in one .xlsx (Item No, Floor, Detail, Nos, L, B, D/H, Qty, Type, RowID).
   Upload : rows filled in / changed in Excel are read back into the app.
     • Row with RowID  -> that same row is updated (links / % rows / order stay as they are)
     • Row without RowID -> a new row is added at the end of the item
     • If the Item No is not in the estimate, a new item is created from SSR (with rate, CF, lead)
     • Type: (empty)=Normal, D=Deduction, LINK/TOTAL = skip
     • A constant-only formula (=2*3.5+1.2) is stored as a formula; for a cell-reference formula only the value is taken.
   NOTE: deleting a row in Excel does not delete it in the app. */
var ATP_MX_HDR=['Item No','Description','Unit','Floor','Detail / Remark','Nos','L','B','D/H','Qty','Type','RowID'];
var ATP_MX_FL=['G','1st','2nd','3rd','4th'];
function atpMxNum(s){
  if(s===null||s===undefined)return null;
  s=String(s).replace(/[,\s\u00a0]/g,'');
  if(s==='')return null;
  var v=parseFloat(s);
  return isNaN(v)?null:v;
}
/* Excel formula -> app formula ('=...') if all operands are numbers, otherwise null */
function atpMxFormula(f){
  if(!f)return null;
  var e=String(f).trim();
  if(e.charAt(0)!=='=')return null;
  e=e.substring(1).replace(/\s+/g,'');
  var g=0;
  while(/(SUM|AVERAGE)\(([^()]*)\)/i.test(e)&&g++<10){
    e=e.replace(/(SUM|AVERAGE)\(([^()]*)\)/ig,function(m,fn,args){
      var p=args.split(/[,;]/),k;
      for(k=0;k<p.length;k++)if(!/^[0-9]*\.?[0-9]+$/.test(p[k]))return 'X';
      var q='('+p.join('+')+')';
      return /^AVERAGE$/i.test(fn)?'('+q+'/'+p.length+')':q;
    });
  }
  if(!e||!/^[0-9+\-*\/().]+$/.test(e)||e.indexOf('//')>-1||e.indexOf('**')>-1)return null;
  try{var r=Function('"use strict";return ('+e+')')();if(typeof r!=='number'||!isFinite(r))return null;}catch(x){return null;}
  return '='+e;
}

/* ── LINKS: Excel cell reference  <->  app link syntax (=N.rF : N=item no., r=row no. (counted from 0), F=L/B/D/N) ──
   Download: app =1.0L*2  ->  Excel =G2*2        Upload: Excel =G2*2 -> app =1.0L*2 (live link) */
function atpMxTokToExcel(tf,erMap){
  var e=String(tf).replace(/\s+/g,''),bad=false;
  if(e.charAt(0)!=='=')return null;
  e=e.substring(1);
  e=e.replace(/(\d+)\.(\d*)([LBDHN])/gi,function(m,ino,rno,fld){
    var er=erMap[(parseInt(ino,10)-1)+'.'+(rno===''?0:parseInt(rno,10))];
    if(!er){bad=true;return 'X';}
    return ({L:'G',B:'H',D:'I',H:'I',N:'F'})[fld.toUpperCase()]+er;
  });
  if(bad)return null;
  var chk=e.replace(/[A-Z]\d+/g,'0');
  if(!chk||!/^[0-9+\-*\/().]+$/.test(chk)||chk.indexOf('//')>-1||chk.indexOf('**')>-1)return null;
  return e;
}
/* only a single-cell reference (=G2) to the same field (L cell -> G column) -> xmap entry of the source row, otherwise null */
function atpMxPureRef(xf,colField,xmap,field){
  var e=String(xf).replace(/[\s$]/g,'');
  if(e.charAt(0)==='=')e=e.substring(1);
  var m=/^([A-Z]{1,3})(\d+)$/i.exec(e);if(!m)return null;
  var fld=colField[m[1].toUpperCase()];
  if(!fld||fld.toLowerCase()!==field)return null;
  return xmap[parseInt(m[2],10)]||null;
}
/* xf = Excel formula, xmap = {excelRow:{it,r}}, colField = {'G':'L',...}, self = {r,f} */
function atpMxLinkFormula(xf,xmap,colField,self){
  var e=String(xf).replace(/\s+/g,'').replace(/\$/g,'');
  if(e.charAt(0)==='=')e=e.substring(1);
  if(!e||/[!'"]/.test(e))return null;
  var ok=true,g=0;
  while(/(SUM|AVERAGE)\(([^()]*)\)/i.test(e)&&g++<20){
    e=e.replace(/(SUM|AVERAGE)\(([^()]*)\)/ig,function(m,fn,args){
      var parts=[],a=args.split(','),k;
      for(k=0;k<a.length;k++){
        var seg=a[k],rm=/^([A-Z]{1,3})(\d+):([A-Z]{1,3})(\d+)$/i.exec(seg);
        if(rm){
          if(rm[1].toUpperCase()!==rm[3].toUpperCase()){ok=false;return 'X';}
          var r1=+rm[2],r2=+rm[4],t;if(r1>r2){t=r1;r1=r2;r2=t;}
          if(r2-r1>200){ok=false;return 'X';}
          for(var q=r1;q<=r2;q++)parts.push(rm[1].toUpperCase()+q);
        }else if(/^[0-9]*\.?[0-9]+$/.test(seg)||/^[A-Z]{1,3}\d+$/i.test(seg))parts.push(seg);
        else{ok=false;return 'X';}
      }
      var sum='('+parts.join('+')+')';
      return /^AVERAGE$/i.test(fn)?'('+sum+'/'+parts.length+')':sum;
    });
  }
  if(!ok)return null;
  var bad=false;
  e=e.replace(/([A-Z]{1,3})(\d+)/gi,function(m,c,rn){
    var fld=colField[c.toUpperCase()],xm=xmap[parseInt(rn,10)];
    if(!fld||!xm){bad=true;return 'X';}
    if(xm.r===self.r&&fld.toLowerCase()===self.f){bad=true;return 'X';}      /* reference to its own cell = circular */
    var ii=items.indexOf(xm.it);
    var ri=xm.it.rows.filter(function(x){return !x.isTot;}).indexOf(xm.r);
    if(ii<0||ri<0){bad=true;return 'X';}
    return (ii+1)+'.'+ri+fld;
  });
  if(bad)return null;
  var chk=e.replace(/\d+\.\d+[LBDN]/g,'0');
  if(!/^[0-9+\-*\/().]+$/.test(chk)||chk.indexOf('//')>-1||chk.indexOf('**')>-1)return null;
  return '='+e;
}
function atpMxToast(m,t){if(typeof showToast==='function')showToast(m,t||'info');else alert(m);}
function atpMxFlName(it,k){return flLabel(it,k||0,ATP_MX_FL);}
function atpMxFlIdx(it,txt){
  var s=String(txt==null?'':txt).trim().toLowerCase();if(!s)return null;
  var b=flBands(it),n=b?b.length:5,k,sets=[ATP_MX_FL,FL_STD_FORM,FL_STD_LONG];
  for(k=0;k<n;k++){
    if(flLabel(it,k,ATP_MX_FL).toLowerCase()===s)return k;
    for(var q=0;q<sets.length;q++)if(!b&&String(sets[q][k]).toLowerCase()===s)return k;
  }
  if(!b){if(s==='ground'||s==='ground floor'||s==='gf'||s==='g')return 0;}
  return null;
}
function atpMxEvalF(fx){
  try{var v=Function('"use strict";return ('+String(fx).substring(1)+')')();return(typeof v==='number'&&isFinite(v))?v:null;}catch(e){return null;}
}
function atpMxCol(i){return String.fromCharCode(65+i);}

/* ── EXCEL WRITER: ExcelJS (dropdowns) -> fallback SheetJS (no dropdowns) ── */
var ATP_MX_FL_LIST='G,1st,2nd,3rd,4th';
var ATP_MX_TYPE_LIST='Normal,Deduction';
var ATP_MX_W=[10,38,7,8,30,7,9,9,9,11,10,12,3,118];   /* A..L = table, M = gap, N = RULES */
/* RULES — shown on the right side of the table (column N) inside the Excel sheet. Column N is not read on upload. */
function atpMxRules(){
  return [
    '📘 RULES — read these before filling the table  (this column N is not read on upload)',
    '▶ HOW TO FILL THE TABLE',
    '1) Write the Item No (same as SSR, as text). Leave Description / Unit / Rate blank — on upload the app picks them up from SSR automatically.',
    '2) Write as many rows for an item as you need. Writing the Item No in the first row is enough;',
    '    if the Item No is left blank in the following rows, they belong to the previous item. For the next item: write the new Item No.',
    '3) Select Floor and Type from the dropdown. If Floor is blank, the floor of the previous row is used (first = G).',
    '4) Type: blank = Normal, Deduction = minus (qty is subtracted). LINK / TOTAL rows are skipped on upload.',
    '5) Fill Nos, L, B, D/H. The app calculates Qty by itself = Nos x L x B x D/H (blank / 0 values are not multiplied).',
    '6) If you have already calculated the total yourself, leave Nos/L/B/D blank and put a constant in the Qty column — it is taken directly.',
    '    (The app does not read a formula in the Qty column; it is only for your own checking.)',
    '▶ FORMULA / LINK',
    '7) Formulas work in Nos/L/B/D: =2*3.5+1.2 (constant formula — it is stored in the app as a formula).',
    '8) A reference to another row = LIVE LINK. Columns: F = Nos, G = L, H = B, I = D/H.',
    '    a) Only a reference, to the same column (=G2 in L, =F2 in Nos, =H2 in B, =I2 in D) => BLUE 🔗 Linked row in the app',
    '        (cell is blue + readonly, ✂ Unlink button). All link-cells of this row must point to the same source row; Type (Normal/Deduction) must be the same.',
    '    b) A calculation (=G2*2, =H2+H3, =SUM(G2:G4) in L, =F2+1 in Nos) => GREEN ƒ Link (cell is green, ƒ badge, the formula shows on hover).',
    '    Both are live: when the L/B/D/Nos of the source row changes, these update automatically. The source row must be in this same file (with an Item No + number).',
    '    To remove a link: blue = ✂ Unlink; green = type a new value in that cell.',
    '9) Not supported (only the value calculated by Excel is taken): reference to Qty (J), reference to another sheet,',
    '    functions like IF / VLOOKUP, a range spanning different columns, a reference to the cell itself (circular).',
    '▶ ROW ID (column L)',
    '10) RowID = the identifier the app uses for a row (the app writes it in Download Current). Do not change it or copy-paste it. Keep it blank in the template.',
    '11) A row with a RowID = updated.  Blank RowID = new row added.  If a RowID is copied to another row, that repeated row is added as a new row.',
    '12) If the values of a row with a RowID are cleared (left blank), that row is skipped — the row in the app stays as it is (it is not deleted / zeroed).',
    '▶ SKIPPED ROWS / COMMON MISTAKES',
    '13) These are skipped: completely blank rows; rows without an Item No (and with no item above them); Item Nos that are not in SSR;',
    '      rows that have only Detail text and none of Nos/L/B/D/Qty. A summary is shown before the upload — check it carefully.',
    '14) If a new Item No exists in SSR, the item is created automatically (with rate, CF, lead) — added at the end of the estimate.',
    '15) If a row is deleted in Excel, it is not deleted in the app (delete it in the app itself). % rows are not in this sheet.',
    '16) If the same file is uploaded twice, rows without a RowID are added both times.'
  ];
}
function atpMxAddRules(aoa){
  var lines=atpMxRules(),i;
  for(i=0;i<lines.length;i++){
    if(!aoa[i])aoa[i]=[];
    while(aoa[i].length<13)aoa[i].push('');
    aoa[i][13]=lines[i];
  }
  return aoa;
}
function atpMxLoadExcelJS(cb){
  if(window.ExcelJS){cb(window.ExcelJS);return;}
  var sc=document.createElement('script');
  sc.src='https://cdnjs.cloudflare.com/ajax/libs/exceljs/4.4.0/exceljs.min.js';
  sc.onload=function(){cb(window.ExcelJS||null);};
  sc.onerror=function(){cb(null);};
  document.head.appendChild(sc);
}
function atpMxDownload(buf,name){
  var blob=new Blob([buf],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});
  var a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;
  document.body.appendChild(a);a.click();
  setTimeout(function(){URL.revokeObjectURL(a.href);a.remove();},1500);
}
/* o={file,aoa,fcells:[{a,f,v}],flRows:{excelRow:'list'},dvRows:lastRowForDropdowns,tpl:bool,okMsg} */
function atpMxSave(o){
  o.aoa=atpMxAddRules(o.aoa);
  atpMxLoadExcelJS(function(EJ){
    if(!EJ){atpMxSaveSJ(o,true);return;}
    try{atpMxSaveEJ(EJ,o);}catch(e){console.error(e);atpMxSaveSJ(o,true);}
  });
}
function atpMxSaveEJ(EJ,o){
  var wb=new EJ.Workbook(),ws=wb.addWorksheet('Measurement',{views:[{state:'frozen',ySplit:1}]}),i,j;
  ws.columns=ATP_MX_W.map(function(w){return {width:w};});
  o.aoa.forEach(function(row){ws.addRow(row.map(function(v){return(v===''||v===undefined)?null:v;}));});
  var hr=ws.getRow(1);hr.font={bold:true,color:{argb:'FFFFFFFF'}};
  hr.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF1A237E'}};
  o.fcells.forEach(function(c){ws.getCell(c.a).value={formula:c.f,result:c.v};});
  var last=Math.max(o.dvRows||o.aoa.length,o.aoa.length);
  for(i=2;i<=last;i++){
    ws.getCell(i,1).numFmt='@';   /* keep Item No as text (so 2.10 does not become 2.1) */
    var fl=(o.flRows&&o.flRows[i])||ATP_MX_FL_LIST;
    ws.getCell(i,4).dataValidation={type:'list',allowBlank:true,formulae:['"'+fl+'"'],showErrorMessage:true,errorStyle:'warning',errorTitle:'Floor',error:'Select the floor from the dropdown'};
    ws.getCell(i,11).dataValidation={type:'list',allowBlank:true,formulae:['"'+ATP_MX_TYPE_LIST+'"'],showErrorMessage:true,errorStyle:'warning',errorTitle:'Type',error:'Select Normal or Deduction'};
  }
  for(i=2;i<=o.aoa.length;i++){var ro=o.aoa[i-1];if(ro&&ro[10]==='TOTAL')ws.getRow(i).font={bold:true};}
  /* styling of the RULES column (N) */
  var nl=atpMxRules();
  nl.forEach(function(t,k){
    var c=ws.getCell(k+1,14);
    if(k===0){c.font={bold:true,color:{argb:'FFFFFFFF'}};c.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FFE65100'}};}
    else if(t.charAt(0)==='▶'){c.font={bold:true,color:{argb:'FFC62828'}};}
    else{c.font={color:{argb:'FF263238'}};}
  });
  wb.xlsx.writeBuffer().then(function(buf){
    atpMxDownload(buf,o.file);atpMxToast(o.okMsg,'success');
  }).catch(function(e){console.error(e);atpMxSaveSJ(o,true);});
}
function atpMxSaveSJ(o,warn){
  if(typeof XLSX==='undefined'){atpMxToast('SheetJS not loaded','error');return;}
  var ws=XLSX.utils.aoa_to_sheet(o.aoa);
  o.fcells.forEach(function(c){ws[c.a]={t:'n',v:c.v,f:c.f};});
  ws['!cols']=ATP_MX_W.map(function(w){return {wch:w};});
  var wb=XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb,ws,'Measurement');
  XLSX.writeFile(wb,o.file);
  atpMxToast(o.okMsg+(warn?' (no dropdowns — ExcelJS did not load; type Floor G/1st/2nd/3rd/4th & Type Deduction yourself)':''),warn?'info':'success');
}

/* ── DOWNLOAD (current estimate) ── */
function atpMxExport(){
  if(!items.length){atpMxToast('No items in the estimate','error');return;}
  var aoa=[ATP_MX_HDR.slice()],fcells=[],flRows={},stamp=Date.now().toString(36),seq=0;
  /* pre-pass: Excel row number of every (item,row) — to convert link formulas (=1.0L*2) into Excel refs (G2*2) */
  var erMap={},er0=2;
  items.forEach(function(it,ii){
    if(!it.rows)return;
    var real=0,any0=false;
    it.rows.forEach(function(r){if(!r||r.isTot)return;if(!r.isPct){erMap[ii+'.'+real]=er0++;any0=true;}real++;});
    if(any0)er0+=2;
  });
  items.forEach(function(it){
    if(!it.rows)return;
    var firstEr=aoa.length+1,lastEr=firstEr-1,any=false;
    var bands=flBands(it),nFl=bands?bands.length:5,fl=[],k;
    for(k=0;k<nFl;k++)fl.push(atpMxFlName(it,k));
    var flStr=fl.join(',');
    var flOk=flStr.length<250&&fl.every(function(x){return String(x).indexOf(',')<0&&String(x).indexOf('"')<0;});
    it.rows.forEach(function(r){
      if(!r||r.isTot||r.isPct)return;
      if(!r._xid)r._xid='r'+stamp+(seq++).toString(36);
      var er=aoa.length+1,lk=!!r._linkedFrom;
      var type=lk?'LINK':(r.isDeduct?'Deduction':'');
      var row=[it.no,any?'':(it.desc||''),any?'':(it.unit||''),atpMxFlName(it,r.fl),r.lbl||'',r.n||1,'','','','',type,r._xid];
      if(!lk&&r._f&&r._f.n){   /* formula / link in Nos */
        var fxn=atpMxFormula(r._f.n),xn=fxn?fxn.substring(1):atpMxTokToExcel(r._f.n,erMap);
        if(xn)fcells.push({a:'F'+er,f:xn,v:r.n||1});
      }
      ['l','b','d'].forEach(function(f,fi){
        var v=r[f],cIdx=6+fi;
        row[cIdx]=(v!=null&&v!==0)?v:'';
        var xf=null;
        if(!lk&&r._f&&r._f[f]){var fx0=atpMxFormula(r._f[f]);xf=fx0?fx0.substring(1):atpMxTokToExcel(r._f[f],erMap);}
        if(xf)fcells.push({a:atpMxCol(cIdx)+er,f:xf,v:(v!=null?v:0)});
      });
      var qf='IF(OR(K'+er+'="D",K'+er+'="Deduction"),-1,1)*IF(N(F'+er+')=0,1,F'+er+')*IF(N(G'+er+')=0,1,G'+er+')*IF(N(H'+er+')=0,1,H'+er+')*IF(N(I'+er+')=0,1,I'+er+')';
      if(!lk)fcells.push({a:'J'+er,f:qf,v:r.qty||0});else row[9]=r.qty||0;
      if(flOk&&flStr!==ATP_MX_FL_LIST)flRows[er]=flStr;
      aoa.push(row);any=true;lastEr=er;
    });
    if(any){
      var te=aoa.length+1;
      aoa.push([it.no,'','','','Total','','','','','','TOTAL','']);
      fcells.push({a:'J'+te,f:'SUM(J'+firstEr+':J'+lastEr+')',v:it.qty||0});
      aoa.push([]);
    }
  });
  var d=new Date(),p=function(n){return(n<10?'0':'')+n;};
  atpMxSave({file:'Measurement_'+d.getFullYear()+p(d.getMonth()+1)+p(d.getDate())+'.xlsx',aoa:aoa,fcells:fcells,flRows:flRows,
    dvRows:aoa.length+60,tpl:false,okMsg:'Measurement Excel downloaded'});
}

/* ── BLANK TEMPLATE (only headings + dropdowns) ── */
function atpMxTemplate(){
  atpMxSave({file:'Measurement_Template.xlsx',aoa:[ATP_MX_HDR.slice()],fcells:[],flRows:{},dvRows:500,tpl:true,
    okMsg:'Blank Measurement template downloaded'});
}

/* ── UPLOAD ── */
function atpMxFindItem(no){
  var k,s=String(no).trim();
  for(k=0;k<items.length;k++)if(String(items[k].no).trim()===s)return k;
  var f=parseFloat(s),hit=-1,cnt=0;
  if(!isNaN(f)){for(k=0;k<items.length;k++)if(parseFloat(items[k].no)===f&&String(items[k].no).trim().replace(/0+$/,'')===s.replace(/0+$/,'')){hit=k;cnt++;}}
  return cnt===1?hit:-1;
}
function atpMxFindSSR(no){
  var k,s=String(no).trim();
  for(k=0;k<SSR.length;k++)if(String(SSR[k][0]).trim()===s)return SSR[k];
  var f=parseFloat(s),hit=null,cnt=0;
  if(!isNaN(f)){for(k=0;k<SSR.length;k++)if(parseFloat(SSR[k][0])===f&&String(SSR[k][0]).trim().replace(/0+$/,'')===s.replace(/0+$/,'')){hit=SSR[k];cnt++;}}
  return cnt===1?hit:null;
}
function atpMxNewItem(d){
  var no=d[0],keyF=String(parseFloat(no));
  var cf=CF_MAP[no]||CF_MAP[keyF]||{};
  var raw=SCADA[no]||SCADA[keyF]||0,sv=(raw&&!CANCEL_SCADA)?scadaScaled(raw):0;
  var res=calcItemLead(cf),rate=d[3]||0,fr=Math.round((rate+res.total+sv)*100)/100;
  items.push({id:Date.now()+items.length,no:no,desc:(d[1]||''),unit:uClean(d[2]||''),spec:(d[4]||''),
    baseRate:rate,cf:cf,scadaVal:sv,leadPerUnit:Math.round(res.total*100)/100,leadMats:res.mats,
    finalRate:fr,qty:0,rows:[],amount:0});
  return items.length-1;
}
function atpMxParse(ws){
  var ref=ws['!ref'];if(!ref)return {err:'Sheet is empty'};
  var rg=XLSX.utils.decode_range(ref),r,c,hr=-1,map={};
  var cellAt=function(rr,cc){return ws[XLSX.utils.encode_cell({r:rr,c:cc})];};
  for(r=rg.s.r;r<=Math.min(rg.e.r,rg.s.r+15)&&hr<0;r++){
    for(c=rg.s.c;c<=rg.e.c;c++){var h=cellAt(r,c);if(h&&String(h.v).trim().toLowerCase()==='item no'){hr=r;break;}}
  }
  if(hr<0)return {err:'"Item No" header not found — use a sheet downloaded from the app'};
  for(c=rg.s.c;c<=rg.e.c;c++){
    var hc=cellAt(hr,c);if(!hc)continue;
    var t=String(hc.v).trim().toLowerCase();
    if(t==='item no')map.no=c;else if(t==='floor')map.fl=c;else if(t.indexOf('detail')===0)map.lbl=c;
    else if(t==='nos'||t==='n')map.n=c;else if(t==='l')map.l=c;else if(t==='b')map.b=c;
    else if(t==='d/h'||t==='d'||t==='h')map.d=c;else if(t==='qty')map.qty=c;else if(t==='type')map.type=c;else if(t==='rowid')map.rid=c;
  }
  if(map.no==null)return {err:'Item No column not found'};
  var ops=[],prev='',noCache=0,refF=0,orphans=[],noNum=[],dups=0,seenRid={},ridRows=[];
  var txt=function(cc){var x=cc==null?null:cellAt(r,cc);return(x&&x.v!=null)?String(x.v).trim():'';};
  var num=function(cc,isQty){
    var x=cc==null?null:cellAt(r,cc);if(!x)return {has:false};
    /* Qty column formula (auto-calculated by Excel) is ignored — only a constant / constant-formula typed by you is taken */
    if(isQty&&x.f&&!atpMxFormula('='+x.f))return {has:false};
    var fx=x.f?atpMxFormula('='+x.f):null,val=null;
    if(fx)val=atpMxEvalF(fx);
    var xf=null;
    if(val===null){fx=null;if(x.t!=='e')val=atpMxNum(x.v);if(x.f){xf=x.f;refF++;if(x.v==null)noCache++;}}
    var has=(val!==null)||(x.v!=null&&String(x.v).trim()!=='')||!!xf;
    return {has:has,val:val,fx:fx,xf:xf};
  };
  for(r=hr+1;r<=rg.e.r;r++){
    var tU=txt(map.type).toUpperCase();
    var type=(tU==='D'||tU==='DED'||tU==='DEDUCT'||tU==='DEDUCTION')?'D':tU;
    if(type==='TOTAL')continue;
    if(type==='LINK'){var lr=txt(map.rid);if(lr)ridRows.push({row:r+1,rid:lr});continue;}   /* LINK rows are skipped on upload, but may be referenced by other rows */
    var no=txt(map.no);if(no)prev=no;else no=prev;
    var o={no:no,type:type,rid:txt(map.rid),lbl:txt(map.lbl),flTxt:txt(map.fl),n:num(map.n),l:num(map.l),b:num(map.b),d:num(map.d),q:num(map.qty,true),row:r+1};
    var hasNum=o.n.has||o.l.has||o.b.has||o.d.has||(o.q.has&&o.q.val);
    if(!hasNum){if(o.lbl)noNum.push(r+1);continue;}   /* empty row / text-only = skip (so that qty doesn't become 1) */
    if(!no){orphans.push(r+1);continue;}                                                /* has data but no Item No */
    if(o.rid)ridRows.push({row:r+1,rid:o.rid});
    if(o.rid){if(seenRid[o.rid]){o.rid='';dups++;}else seenRid[o.rid]=1;}               /* copied row = new row */
    ops.push(o);
  }
  var colField={};
  ['n','l','b','d'].forEach(function(f){if(map[f]!=null)colField[XLSX.utils.encode_col(map[f])]=f.toUpperCase();});
  return {ops:ops,noCache:noCache,refF:refF,orphans:orphans,noNum:noNum,dups:dups,colField:colField,ridRows:ridRows};
}
function atpMxApply(P){
  var upd=0,add=0,newIt=0,skipLink=0,unknown={},ci,created={};
  /* pass 1: dry run for the summary */
  var st={upd:0,add:0,newIt:0,unk:{},cnt:{}},seenNew={};
  P.ops.forEach(function(o){
    var ix=atpMxFindItem(o.no);
    if(ix<0){
      if(!atpMxFindSSR(o.no)){st.unk[o.no]=1;o.skip=true;return;}
      if(!seenNew[o.no]){seenNew[o.no]=1;st.newIt++;}
      st.add++;st.cnt[o.no]=(st.cnt[o.no]||0)+1;return;
    }
    st.cnt[items[ix].no]=(st.cnt[items[ix].no]||0)+1;
    var found=false;
    if(o.rid)(items[ix].rows||[]).forEach(function(r){if(r._xid===o.rid)found=true;});
    if(found)st.upd++;else st.add++;
  });
  var unk=Object.keys(st.unk);
  var msg='Excel Upload:\n• Will update: '+st.upd+' row(s)\n• New rows: '+st.add+'\n• New items (from SSR): '+st.newIt;
  var ck=Object.keys(st.cnt);
  if(ck.length)msg+='\n• Item-wise rows: '+ck.slice(0,10).map(function(k){return k+' ('+st.cnt[k]+')';}).join(', ')+(ck.length>10?' …':'');
  if(unk.length)msg+='\n• Item No not found (skipped): '+unk.join(', ');
  if(P.orphans&&P.orphans.length)msg+='\n• Skipped, no Item No (Excel row): '+P.orphans.slice(0,12).join(', ')+(P.orphans.length>12?' …':'');
  if(P.noNum&&P.noNum.length)msg+='\n• Skipped, no number (Nos/L/B/D/Qty) (Excel row): '+P.noNum.slice(0,12).join(', ')+(P.noNum.length>12?' …':'');
  if(P.dups)msg+='\n• '+P.dups+' row(s) had a duplicate RowID (copied) — will be added as new rows';
  if(P.refF)msg+='\n• '+P.refF+' cell(s) have a cell-reference formula — where possible (L/B/D/Nos cells) a link (=1.0L) is created in the app, otherwise only the value';
  if(P.noCache)msg+='\n• '+P.noCache+' formula cell(s) had no saved value (save in Excel and upload again) — taken as blank';
  if(!st.upd&&!st.add){alert('Nothing found to upload.'+(unk.length?'\nItem No not found: '+unk.join(', '):'')+(P.orphans&&P.orphans.length?'\nNo Item No (Excel row): '+P.orphans.join(', '):'')+(P.noNum&&P.noNum.length?'\nNo number (Excel row): '+P.noNum.join(', '):''));return;}
  if(!confirm(msg+'\n\nContinue?'))return;
  /* pass 2: apply */
  var lastFl={},xmap={},pend=[];
  /* all Excel rows with a RowID (incl. LINK) -> app row, so references to them can be resolved */
  var ridIdx={};
  items.forEach(function(x){(x.rows||[]).forEach(function(rw){if(rw&&rw._xid)ridIdx[rw._xid]={it:x,r:rw};});});
  (P.ridRows||[]).forEach(function(q){if(ridIdx[q.rid])xmap[q.row]=ridIdx[q.rid];});
  P.ops.forEach(function(o){
    if(o.skip)return;
    var ix=atpMxFindItem(o.no);
    if(ix<0){var d=atpMxFindSSR(o.no);if(!d)return;ix=atpMxNewItem(d);}
    var it=items[ix];if(!it.rows)it.rows=[];
    var r=null,isNew=false;
    if(!o.rid&&!it._mxCleaned){
      /* empty placeholder row added by the app (only 1 row, nothing in it) -> remove it before the new rows */
      it._mxCleaned=true;
      var nt=it.rows.filter(function(x){return !x.isTot;});
      if(nt.length===1){
        var z=nt[0];
        var blank=!z.isPct&&!z._linkedFrom&&!z.lbl&&!z.comment&&(z.n==null||z.n===1)&&!z.l&&!z.b&&!z.d&&!(z._f&&Object.keys(z._f).length);
        if(blank)it.rows.splice(it.rows.indexOf(z),1);
      }
    }
    if(o.rid){for(ci=0;ci<it.rows.length;ci++)if(it.rows[ci]._xid===o.rid){r=it.rows[ci];break;}}
    if(r&&(r.isTot||r.isPct||r._linkedFrom)){skipLink++;return;}
    if(!r){
      isNew=true;
      r={lbl:'',n:1,l:0,b:0,d:0,qty:0,fl:msrLastFloor(it)};
      var ti=it.rows.findIndex(function(x){return x.isTot;});
      if(ti>=0)it.rows.splice(ti,0,r);else it.rows.push(r);
    }
    if(o.type==='D')r.isDeduct=true;else delete r.isDeduct;
    /* if Floor is empty, use the floor of the previous row of this item in this upload, otherwise G */
    var fl=atpMxFlIdx(it,o.flTxt);
    if(fl!==null)r.fl=fl;
    else if(isNew)r.fl=(lastFl[it.no]!=null)?lastFl[it.no]:0;
    lastFl[it.no]=r.fl||0;
    r.lbl=o.lbl;
    if(!r._f)r._f={};
    /* Nos: constant formula -> _f.n ; cell-reference -> link (pend) ; otherwise plain value */
    if(o.n.fx){r._f.n=o.n.fx;r.n=o.n.val||1;}
    else{delete r._f.n;r.n=(o.n.val||1);if(o.n.xf)pend.push({r:r,f:'n',xf:o.n.xf});}
    ['l','b','d'].forEach(function(f){
      var x=o[f];
      if(o.rid&&!x.has&&!isNew){r[f]=null;delete r._f[f];return;}
      if(x.fx)r._f[f]=x.fx;else delete r._f[f];
      r[f]=(x.val!==null&&x.val!==undefined)?x.val:null;
      if(x.xf)pend.push({r:r,f:f,xf:x.xf});                 /* cell-reference formula: convert to a link after all rows are done */
    });
    xmap[o.row]={it:it,r:r};
    if(o.q&&o.q.has&&o.q.val!==null&&o.q.val!==undefined&&!o.l.has&&!o.b.has&&!o.d.has){
      /* no L/B/D, Qty given directly -> keep it in Nos (qty = Nos) */
      r.n=(o.type==='D')?Math.abs(o.q.val):o.q.val;
      delete r._f.n;pend=pend.filter(function(p){return !(p.r===r&&p.f==='n');});
    }
    if(isNew)add++;else upd++;
  });
  items.forEach(function(x){delete x._mxCleaned;});
  /* regroup floor-wise first (row numbers become final), then Excel refs -> =N.rF links */
  msrRegroupAll();
  var linked=0,valOnly=0,nat=0,groups=[];
  pend.forEach(function(p){
    var g=null,k;for(k=0;k<groups.length;k++)if(groups[k].r===p.r){g=groups[k];break;}
    if(!g){g={r:p.r,list:[]};groups.push(g);}g.list.push(p);
  });
  groups.forEach(function(g){
    var r=g.r,src=null,same=true,flds=[];
    /* 1) all cells are only same-field references (L=G2, Nos=F2 ...) to a single source row -> the app's blue 🔗 row link */
    g.list.forEach(function(p){
      var xm=atpMxPureRef(p.xf,P.colField||{},xmap,p.f);
      if(!xm||xm.r===r){same=false;return;}
      if(src===null)src=xm;else if(src.r!==xm.r)same=false;
      flds.push(p.f);
    });
    if(same&&src&&!!src.r.isDeduct===!!r.isDeduct){
      var sIi=items.indexOf(src.it),sRi=src.it.rows.indexOf(src.r);
      if(sIi>=0&&sRi>=0){
        r._linkedFrom={iIdx:sIi,rIdx:sRi,fields:['n','l','b','d'].filter(function(f){return flds.indexOf(f)>-1;}),pct:100};
        if(r._f)flds.forEach(function(f){delete r._f[f];});
        nat+=g.list.length;return;
      }
    }
    /* 2) calculation / mixed -> green ƒ formula link (=1.0L*2) */
    g.list.forEach(function(p){
      var lf=atpMxLinkFormula(p.xf,xmap,P.colField||{},p);
      if(lf){if(!p.r._f)p.r._f={};p.r._f[p.f]=lf;linked++;}else valOnly++;
    });
  });
  msrSyncAllRows();
  for(var a=0;a<items.length;a++)items[a]=recalcItem(items[a]);
  rMS();updateAll();
  atpMxToast('Excel upload done: '+upd+' update, '+add+' new row(s)'+(nat?', '+nat+' cell 🔗 link (blue)':'')+(linked?', '+linked+' cell ƒ link (green)':'')+(valOnly?', '+valOnly+' formula(s), only value taken':'')+(skipLink?', '+skipLink+' linked/% skip':''),'success');
}
function atpMxImportFile(file){
  if(!file)return;
  if(typeof XLSX==='undefined'){atpMxToast('SheetJS not loaded','error');return;}
  var rd=new FileReader();
  rd.onload=function(e){
    try{
      var wb=XLSX.read(e.target.result,{type:'array'});
      var ws=wb.Sheets['Measurement']||wb.Sheets[wb.SheetNames[0]];
      var P=atpMxParse(ws);
      if(P.err){alert(P.err);return;}
      atpMxApply(P);
    }catch(err){alert('Could not read Excel: '+err.message);}
  };
  rd.readAsArrayBuffer(file);
}
function atpMxUploadClick(){
  var inp=document.getElementById('atpMxFile');
  if(!inp){
    inp=document.createElement('input');inp.type='file';inp.id='atpMxFile';
    inp.accept='.xlsx,.xls';inp.style.display='none';
    inp.onchange=function(){atpMxImportFile(inp.files[0]);inp.value='';};
    document.body.appendChild(inp);
  }
  inp.click();
}
function atpMxInject(){
  var p5=document.getElementById('p5');if(!p5||document.getElementById('mxBar'))return;
  var tw=p5.querySelector('.tw');if(!tw)return;
  var d=document.createElement('div');d.id='mxBar';d.className='noprt';d.style.cssText='margin:.4rem 0;display:flex;gap:.4rem;flex-wrap:wrap';
  d.innerHTML='<button class="btn" onclick="atpMxTemplate()" title="Blank Excel with only headings" style="background:#455a64;color:#fff;font-size:.62rem;padding:.3rem .7rem">📄 Blank Template</button>'
    +'<button class="btn" onclick="atpMxExport()" title="Download the measurement sheet as Excel" style="background:#2e7d32;color:#fff;font-size:.62rem;padding:.3rem .7rem">⬇ Current Measurement Download</button>'
    +'<button class="btn" onclick="atpMxUploadClick()" title="Load the measurements filled in Excel back into the app" style="background:#e65100;color:#fff;font-size:.62rem;padding:.3rem .7rem">⬆ Measurement Excel Upload</button>';
  tw.parentNode.insertBefore(d,tw);
}
if(document.readyState!=='loading')setTimeout(atpMxInject,700);
else document.addEventListener('DOMContentLoaded',function(){setTimeout(atpMxInject,700);});


/* ═══ SESSION AUTO-RESTORE ═════════════════════════════════════════════════
   After a refresh or power cut, resume from where you were working on the PC.
   - ~1.5 sec after any change, the current estimate is saved (in IndexedDB)
   - When the page is reopened, the last snapshot is loaded automatically (same tab included)
   - The "Save Estimate" saved list is not affected (separate storage)
   Manual clear: run atpSessionClear() in the console
   ======================================================================== */
(function(){
  if(window.__atpSessionInit)return;window.__atpSessionInit=true;
  var DB='atp_session_db',K_MAIN='session',K_BAK='session_backup',LS_KEY='atp_session_v1';
  var S={ready:false,t:null,first:0,last:'',authHooked:false};
  var LM={img:null,w:0,h:0,data:null};

  function _t(f,d){try{var v=f();return v===undefined?d:v;}catch(e){return d;}}
  function toast(m,t){try{if(typeof showToast==='function')showToast(m,t||'success');}catch(e){}}

  /* ── tiny IndexedDB key-value (localStorage fallback) ── */
  function idbOpen(){
    return new Promise(function(res,rej){
      if(!window.indexedDB){rej(new Error('no idb'));return;}
      var rq=indexedDB.open(DB,1);
      rq.onupgradeneeded=function(){rq.result.createObjectStore('kv');};
      rq.onsuccess=function(){res(rq.result);};
      rq.onerror=function(){rej(rq.error);};
    });
  }
  function kvGet(k){
    return idbOpen().then(function(db){
      return new Promise(function(res,rej){
        var q=db.transaction('kv','readonly').objectStore('kv').get(k);
        q.onsuccess=function(){res(q.result||null);};q.onerror=function(){rej(q.error);};
      });
    }).catch(function(){
      try{var v=localStorage.getItem(LS_KEY+(k===K_MAIN?'':'_bak'));return v?JSON.parse(v):null;}catch(e){return null;}
    });
  }
  function kvSet(k,v){
    return idbOpen().then(function(db){
      return new Promise(function(res,rej){
        var tx=db.transaction('kv','readwrite');tx.objectStore('kv').put(v,k);
        tx.oncomplete=function(){res();};tx.onerror=function(){rej(tx.error);};tx.onabort=function(){rej(tx.error);};
      });
    }).catch(function(){
      try{localStorage.setItem(LS_KEY+(k===K_MAIN?'':'_bak'),JSON.stringify(v));}catch(e){}
    });
  }
  function kvDel(k){
    return idbOpen().then(function(db){
      return new Promise(function(res,rej){
        var tx=db.transaction('kv','readwrite');tx.objectStore('kv').delete(k);
        tx.oncomplete=function(){res();};tx.onerror=function(){rej(tx.error);};
      });
    }).catch(function(){
      try{localStorage.removeItem(LS_KEY+(k===K_MAIN?'':'_bak'));}catch(e){}
    });
  }

  /* ── Quarry-chart (lead map) data; background image JPEG is cached ── */
  function leadMapData(){
    if(typeof SP==='undefined'||!SP||!SP.shapes)return null;
    var o={shapes:JSON.parse(JSON.stringify(SP.shapes)),bgImgX:SP.bgImgX||0,bgImgY:SP.bgImgY||0,
      bgImgW:SP.bgImgW||0,bgImgH:SP.bgImgH||0,autoOn:SP.autoOn!==false};
    if(SP.bgImg){
      var w=SP.bgImgW||400,h=SP.bgImgH||300;
      if(LM.img!==SP.bgImg||LM.w!==w||LM.h!==h){
        var data=null;
        try{var c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(SP.bgImg,0,0,w,h);data=c.toDataURL('image/jpeg',0.55);}catch(e){}
        LM={img:SP.bgImg,w:w,h:h,data:data};
      }
      if(LM.data)o.bgImgData=LM.data;
    }
    return o;
  }

  /* ── Full estimate snapshot (same shape as saveEstimate's entry) ── */
  function buildEntry(){
    var nm=((R('pName')||{}).value||'').trim();
    var lkm={};if(typeof LCD!=='undefined'){for(var i=0;i<LCD.length;i++){var el=R('lkm_'+i);if(el)lkm[i]=parseFloat(el.value)||0;}}
    var lkmFull={};if(typeof LEAD_KM!=='undefined'){for(var k in LEAD_KM)lkmFull[k]=LEAD_KM[k];}
    var llocFull={};if(typeof LEAD_LOC!=='undefined'){for(var l in LEAD_LOC)llocFull[l]=LEAD_LOC[l];}
    var mtfSave={};if(typeof mtfData!=='undefined'){for(var j=0;j<mtfData.length;j++)mtfSave[mtfData[j].sr]=mtfData[j].cost;}
    var meta={pName:((R('pName')||{}).value||''),pSub:((R('pSub')||{}).value||''),
      pDiv:((R('pDiv')||{}).value||''),pCir:((R('pCir')||{}).value||''),pReg:((R('pReg')||{}).value||''),
      sGST:pf('sGST'),sCont:pf('sCont'),sContMode:((R('sContMode')||{}).value||'pct'),sLI:pf('sLI'),sRS:pf('sRS'),sRC:pf('sRC')};
    meta.covCostUnit=(window.COV_COST_UNIT||'lakhs');
    meta.covCostManual=(window.COV_COST_MANUAL!=null?window.COV_COST_MANUAL:null);
    meta.cancelScada=_t(function(){return CANCEL_SCADA||false;},false);
    meta.gfOnly=_t(function(){return GF_ONLY||false;},false);
    meta.customScadaVal=_t(function(){return CUSTOM_SCADA_VAL||-126;},-126);
    meta.customScadaBt=_t(function(){return CUSTOM_SCADA_BT!=null?CUSTOM_SCADA_BT:-63;},-63);
    meta.bitHeatVal=_t(function(){return BIT_HEAT_VAL;},137);
    meta.dcmRows=_t(function(){return JSON.parse(JSON.stringify(DCM_ROWS||[]));},[]);
    meta.gstBase=(window.GST_BASE||'A');
    var cc=_t(function(){return cessCfg();},null);
    if(cc){meta.cessOn=cc.on;meta.cessPct=cc.pct;meta.cessScadaFirst=cc.scadaFirst;}
    meta.area=_t(function(){return areaCfgSave();},null);
    return {nm:nm,baseName:nm,dt:new Date().toLocaleDateString('en-IN'),meta:meta,
      lkm:lkm,leadKm:lkmFull,leadLoc:llocFull,lcExtra:(typeof lcExtraForSave==='function'?lcExtraForSave():[]),mtfCosts:mtfSave,
      mtfCustom:_t(function(){return mtfCustomRowsForSave();},[]),
      mtfDesc:_t(function(){return mtfDescOverridesForSave();},{}),
      mtfConc:_t(function(){return typeof mtfConcForSave==='function'?mtfConcForSave():null;},null),
      testReport:_t(function(){return typeof trForSave==='function'?trForSave():null;},null),
      extraRows:(typeof EXTRA_ROWS!=='undefined')?JSON.parse(JSON.stringify(EXTRA_ROWS)):[],
      steelRows:(typeof steelRows!=='undefined')?JSON.parse(JSON.stringify(steelRows)):[],
      scSecs:(typeof scSecs!=='undefined')?JSON.parse(JSON.stringify(scSecs)):[],
      planData:_t(function(){return typeof window._getPlanData==='function'?window._getPlanData():null;},null),
      leadMapData:_t(leadMapData,null),
      items:items};
  }
  function curTab(){
    var n=NaN;
    for(var i=0;i<=21;i++){var p=R('p'+i);if(p&&p.classList&&p.classList.contains('on')){n=i;break;}}
    if(isNaN(n)){try{n=parseInt(sessionStorage.getItem('_lastTab'));}catch(e){}}
    return isNaN(n)?null:n;
  }

  /* ── SAVE ── */
  function save(){
    if(!S.ready)return;
    S.first=0;
    var body;
    try{
      body=JSON.stringify({v:1,tab:curTab(),key:(window.CUR_SAVE_KEY||null),
        estId:_t(function(){return CUR_EST_ID||null;},null),
        uid:_t(function(){return (CU&&CU.uid)||null;},null),entry:buildEntry()});
    }catch(e){return;}
    if(body===S.last)return;
    S.last=body;
    kvSet(K_MAIN,{t:Date.now(),d:body});
  }
  function dirty(){
    if(!S.ready)return;
    var now=Date.now();if(!S.first)S.first=now;
    clearTimeout(S.t);
    /* typing continuously? still force a save every ~8 sec */
    S.t=setTimeout(save,(now-S.first>8000)?0:1500);
  }

  /* ── RESTORE ── */
  function depsOk(snap){
    return typeof R==='function'&&R('pName')&&typeof recalcItem==='function'&&typeof updateAll==='function'
      &&typeof buildLCT==='function'&&typeof dcmRender==='function'&&typeof _atpApplyEstimate==='function'
      &&typeof LCD!=='undefined'&&(!snap.entry||!snap.entry.planData||typeof window._setPlanData==='function');
  }
  function waitDeps(snap,cb){
    var tries=0;
    (function poll(){
      if(depsOk(snap)||++tries>48){cb();return;}   /* max ~12 sec */
      setTimeout(poll,250);
    })();
  }
  function hasWork(est){
    return !!(est&&((est.items&&est.items.length)||(est.meta&&est.meta.pName)||(est.scSecs&&est.scSecs.length)||(est.steelRows&&est.steelRows.length)));
  }
  function restore(snap,ts){
    var est=snap.entry;
    _atpApplyEstimate(est,snap.key||est.nm||'__session__',true);
    window.CUR_SAVE_KEY=snap.key||undefined;
    if(snap.estId){
      var okUser=_t(function(){return !snap.uid||!CU||CU.uid===snap.uid;},true);
      if(okUser){try{CUR_EST_ID=snap.estId;}catch(e){}}
    }
    if(snap.tab!=null&&typeof goTab==='function'){try{goTab(snap.tab);}catch(e){}}
    var d=ts?new Date(ts):null;
    var hm=d?(' ('+d.toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})+' onwards)'):'';
    toast('♻️ Previous work restored'+hm,'success');
  }
  function boot(){
    hookOnce();
    kvGet(K_MAIN).then(function(rec){
      if(!rec||!rec.d){S.ready=true;return;}
      var snap;try{snap=JSON.parse(rec.d);}catch(e){S.ready=true;return;}
      if(!snap||!hasWork(snap.entry)){S.ready=true;return;}
      S.last=rec.d;
      kvSet(K_BAK,rec);   /* if anything breaks during restore, the backup remains */
      waitDeps(snap,function(){
        try{restore(snap,rec.t);}
        catch(e){
          try{console.error('[ATP session restore]',e);}catch(_){}
          toast('Auto-restore failed — backup has been kept','error');
          S.last='';
        }
        setTimeout(function(){S.ready=true;},900);
      });
    }).catch(function(){S.ready=true;});
  }

  /* ── hooks ── */
  function hookOnce(){
    if(window.__atpSessionHooked)return;window.__atpSessionHooked=true;
    ['updateAll','goTab'].forEach(function(fn){
      var o=window[fn];if(typeof o!=='function')return;
      window[fn]=function(){var r=o.apply(this,arguments);dirty();return r;};
    });
    ['input','change','click','keyup','paste'].forEach(function(ev){
      document.addEventListener(ev,dirty,true);
    });
    document.addEventListener('visibilitychange',function(){if(document.hidden){clearTimeout(S.t);save();}});
    window.addEventListener('pagehide',function(){clearTimeout(S.t);save();});
    window.addEventListener('beforeunload',function(){clearTimeout(S.t);save();});
    setInterval(function(){if(S.ready&&S.first)save();},15000);
  }

  window.atpSessionSave=function(){save();};
  window.atpSessionClear=function(){S.last='';return kvDel(K_MAIN).then(function(){toast('Session snapshot cleared','success');});};
  window.atpSessionRestoreBackup=function(){
    return kvGet(K_BAK).then(function(rec){
      if(!rec||!rec.d){toast('No backup found','error');return;}
      restore(JSON.parse(rec.d),rec.t);
    });
  };

  function start(){setTimeout(boot,800);}
  if(document.readyState==='complete')start();else window.addEventListener('load',start);
})();
/* ═══ END SESSION AUTO-RESTORE ═══ */


/* ══════════════════════════════════════════════════════════════════════
   USER PREFERENCES → CLOUD   (Stamp / sign details + sheet-wise stamp config)
   Firestore: userPrefs/{uid}  →  { uid, stamp:{<localStorage key>:value}, clientTs, updatedAt }
   localStorage stays the working copy (so everything keeps working offline);
   every change is pushed (debounced), and after login the cloud copy is pulled.
══════════════════════════════════════════════════════════════════════ */
var ATP_PREF_KEYS=['stampSecEng','stampSubDivEng','stampDE','stampEE','stampSECircle','stampCE',
  'stampSETitle','stampSDETitle','stampDETitle','stampEETitle','stampSECircleTitle','stampCETitle',
  'stampLocSub','stampLocDiv','stampLocCir','stampLocReg','stampSubDivLoc','signHeight','smSheetCfg',
  'schStampDE','schStampEE','schStampDiv','schStampSub'];
var _atpPrefTimer=null;
function _atpPrefsCollect(){
  var o={};
  ATP_PREF_KEYS.forEach(function(k){try{var v=localStorage.getItem(k);if(v!==null&&v!=='')o[k]=String(v);}catch(e){}});
  return o;
}
function atpPrefsPush(){
  clearTimeout(_atpPrefTimer);
  _atpPrefTimer=setTimeout(function(){
    try{
      if(typeof CU==='undefined'||!CU||!window.firebase||!firebase.firestore)return;
      var ts=Date.now();
      firebase.firestore().collection('userPrefs').doc(CU.uid).set({
        uid:CU.uid,stamp:_atpPrefsCollect(),clientTs:ts,updatedAt:firebase.firestore.FieldValue.serverTimestamp()
      }).then(function(){try{localStorage.setItem('atpPrefsSyncedAt',String(ts));}catch(e){}})
        .catch(function(e){try{console.warn('Stamp prefs cloud save failed:',e&&e.message);}catch(_c){}});
    }catch(e){}
  },1500);
}
function atpPrefsPull(){
  try{
    if(typeof CU==='undefined'||!CU||!window.firebase||!firebase.firestore)return;
    firebase.firestore().collection('userPrefs').doc(CU.uid).get().then(function(doc){
      var local=_atpPrefsCollect();
      var synced=parseInt(localStorage.getItem('atpPrefsSyncedAt'),10)||0;
      if(!doc.exists){                       /* first time ever: upload what this device already has */
        if(Object.keys(local).length)atpPrefsPush();
        return;
      }
      var c=doc.data()||{},cs=c.stamp||{},cts=c.clientTs||0;
      var firstOnDevice=(synced===0),changedElsewhere=(synced>0&&cts>synced);
      if(!firstOnDevice&&!changedElsewhere)return;   /* this device is already up to date */
      if(changedElsewhere){ATP_PREF_KEYS.forEach(function(k){try{localStorage.removeItem(k);}catch(e){}});}  /* other device is newer: cloud copy replaces local */
      Object.keys(cs).forEach(function(k){if(ATP_PREF_KEYS.indexOf(k)>=0){try{localStorage.setItem(k,cs[k]);}catch(e){}}});
      try{localStorage.setItem('atpPrefsSyncedAt',String(cts));}catch(e){}
      /* first login on a new device: cloud wins on conflicts, but keep keys only this device had and upload them */
      if(firstOnDevice){var extra=Object.keys(local).some(function(k){return !(k in cs);});if(extra)atpPrefsPush();}
      try{if(typeof updateAllStamps==='function')updateAllStamps();}catch(e){}
      try{var _g=function(i){return document.getElementById(i);};
        if(_g('smSheetConfig')&&typeof smBuildSheetConfig==='function'&&_g('stampModal')&&_g('stampModal').style.display!=='none')smBuildSheetConfig();}catch(e){}
    }).catch(function(e){try{console.warn('Stamp prefs cloud load failed:',e&&e.message);}catch(_c){}});
  }catch(e){}
}
